const lessons = [
{num:1,time:"00:00:00,000 --> 00:00:02,060",arabic:"بَيْنَ صَخْرَةٍ مُعَلَّقَةٍ فِي السَّمَاءِ",segs:null,full_uz:"Osmonda osilib turgan bir qoya orasida.",note:null},
{num:2,time:"00:00:02,060 --> 00:00:05,700",arabic:"وَبَحْرٍ لَا يَغْرَقُ فِيهِ أَحَدٌ",segs:[{ar:"وَبَحْرٍ",uz:"va hech kim cho‘kmaydigan dengiz"},{ar:"لَا يَغْرَقُ فِيهِ أَحَدٌ",uz:"unda hech kim cho‘kmaydi"}],full_uz:"Va unda hech kim cho‘kmaydigan dengiz orasida.",note:null},
{num:3,time:"00:00:05,700 --> 00:00:09,880",arabic:"بَيْنَ زَيْتُونَةٍ تَهْمِسُ بِأَلْفِ عَامٍ",segs:[{ar:"بَيْنَ زَيْتُونَةٍ",uz:"ming yillik zaytun daraxti orasida"},{ar:"تَهْمِسُ بِأَلْفِ عَامٍ",uz:"ming yil haqida shivirlaydigan"}],full_uz:"Ming yil haqida shivirlaydigan zaytun daraxti orasida.",note:"زَيْتُونَةٌ — zaytun daraxti."},
{num:4,time:"00:00:09,880 --> 00:00:15,000",arabic:"وَطِفْلٍ يَرْقُصُ عَلَى إِيقَاعِ الدَّبْكَةِ وَالْحُلْمِ",segs:[{ar:"وَطِفْلٍ يَرْقُصُ",uz:"raqsga tushayotgan bola"},{ar:"عَلَى إِيقَاعِ الدَّبْكَةِ",uz:"dabka ohangida"},{ar:"وَالْحُلْمِ",uz:"va orzu bilan"}],full_uz:"Dabka va orzu ohangida raqsga tushayotgan bola orasida.",note:"الدَّبْكَةُ — arab xalq raqsi."},
{num:5,time:"00:00:15,000 --> 00:00:20,740",arabic:"هُنَاكَ حَيْثُ لَا يَفْصِلُ الرُّوحَ عَنِ التُّرَابِ سِوَى دُعَاءٍ",segs:[{ar:"هُنَاكَ حَيْثُ",uz:"u yerda"},{ar:"لَا يَفْصِلُ الرُّوحَ عَنِ التُّرَابِ",uz:"ruhni tuproqdan ajratmaydi"},{ar:"سِوَى دُعَاءٍ",uz:"faqatgina duo"}],full_uz:"U yerda ruhni tuproqdan faqatgina duo ajratadi.",note:"سِوَى — faqat, ...dan boshqa."},
{num:6,time:"00:00:20,740 --> 00:00:25,580",arabic:"وَحَيْثُ تُعَانِقُ الْجِبَالُ ظِلَّ التَّارِيخِ",segs:[{ar:"وَحَيْثُ تُعَانِقُ الْجِبَالُ",uz:"va tog‘lar quchoqlaydigan joyda"},{ar:"ظِلَّ التَّارِيخِ",uz:"tarix soyasini"}],full_uz:"Tog‘lar tarix soyasini quchoqlaydigan joyda.",note:"تُعَانِقُ — quchoqlamoq."},
{num:7,time:"00:00:25,580 --> 00:00:29,080",arabic:"وَتَكْتُبُ الْحِجَارَةُ قَصَائِدَ لَا تَنْتَهِي",segs:[{ar:"وَتَكْتُبُ الْحِجَارَةُ",uz:"va toshlar yozadi"},{ar:"قَصَائِدَ لَا تَنْتَهِي",uz:"tugamaydigan she’rlarni"}],full_uz:"Va toshlar tugamaydigan she’rlarni yozadi.",note:null},
{num:8,time:"00:00:30,000 --> 00:00:32,700",arabic:"هُنَاكَ فِلَسْطِينُ",segs:null,full_uz:"U yerda Falastin.",note:null},
{num:9,time:"00:00:32,700 --> 00:00:36,380",arabic:"لَيْسَتْ مُجَرَّدَ وَطَنٍ",segs:null,full_uz:"U shunchaki vatan emas.",note:null},
{num:10,time:"00:00:36,380 --> 00:00:39,380",arabic:"بَلْ مِرْآةُ السَّمَاءِ حِينَ تَمَسُّ الْأَرْضَ",segs:[{ar:"بَلْ مِرْآةُ السَّمَاءِ",uz:"balki osmonning ko‘zgusi"},{ar:"حِينَ تَمَسُّ الْأَرْضَ",uz:"yerga tekkanda"}],full_uz:"Balki yerga tekkanda osmonning ko‘zgusidir.",note:"مِرْآةٌ — ko‘zgu."},
{num:11,time:"00:00:39,380 --> 00:00:45,240",arabic:"وَسَجَّادَةٌ مِنْ نُورٍ وَدَمْعٍ وَعِطْرِ يَاسَمِينٍ",segs:[{ar:"وَسَجَّادَةٌ مِنْ نُورٍ وَدَمْعٍ",uz:"nur va yoshdan to‘qilgan sajdagoh"},{ar:"وَعِطْرِ يَاسَمِينٍ",uz:"va yasmin ifori bilan"}],full_uz:"Va nur, yosh hamda yasmin iforidan to‘qilgan sajdagohdir.",note:"سَجَّادَةٌ — gilam, sajdagoh. يَاسَمِينٌ — yasmin."},
{num:12,time:"00:00:45,240 --> 00:00:49,980",arabic:"أَرْضٌ لَا تُرْوَى فَقَطْ بِالْحِكَايَاتِ",segs:[{ar:"أَرْضٌ",uz:"bir yurt"},{ar:"لَا تُرْوَى فَقَطْ بِالْحِكَايَاتِ",uz:"faqat hikoyalar bilan so‘zlab berilmaydigan"}],full_uz:"Faqat hikoyalar bilan so‘zlab berilmaydigan bir yurt.",note:"تُرْوَى — hikoya qilinmoq, so‘zlab berilmoq."},
{num:13,time:"00:00:49,980 --> 00:00:54,159",arabic:"بَلْ تُرَى وَتُحَسُّ وَتُحَبُّ",segs:[{ar:"بَلْ تُرَى",uz:"balki ko‘riladi"},{ar:"وَتُحَسُّ",uz:"his qilinadi"},{ar:"وَتُحَبُّ",uz:"va seviladi"}],full_uz:"Balki ko‘riladi, his qilinadi va seviladi.",note:null},
{num:14,time:"00:00:54,159 --> 00:01:01,219",arabic:"فِي هَذَا الْفِيدْيُو سَنُسَافِرُ بَيْنَ مُعْجِزَاتٍ لَا يَعْرِفُهَا كَثِيرُونَ",segs:[{ar:"فِي هَذَا الْفِيدْيُو",uz:"bu videoda"},{ar:"سَنُسَافِرُ بَيْنَ مُعْجِزَاتٍ",uz:"mo‘jizalar orasida sayohat qilamiz"},{ar:"لَا يَعْرِفُهَا كَثِيرُونَ",uz:"ularni ko‘pchilik bilmaydi"}],full_uz:"Bu videoda ko‘pchilik bilmaydigan mo‘jizalar orasida sayohat qilamiz.",note:null},
{num:15,time:"00:01:01,219 --> 00:01:05,299",arabic:"بَيْنَ مُدُنٍ تَنْبِضُ بِالتَّارِيخِ",segs:[{ar:"بَيْنَ مُدُنٍ",uz:"shaharlar orasida"},{ar:"تَنْبِضُ بِالتَّارِيخِ",uz:"tarix bilan jo‘sh uradigan"}],full_uz:"Tarix bilan jo‘sh uradigan shaharlar orasida.",note:"تَنْبِضُ — urmoq, jo‘sh urmoq."},
{num:16,time:"00:01:05,299 --> 00:01:10,340",arabic:"وَأَوْدِيَةٍ تَنَامُ فِيهَا الْأَسَاطِيرُ",segs:[{ar:"وَأَوْدِيَةٍ",uz:"vodiylar orasida"},{ar:"تَنَامُ فِيهَا الْأَسَاطِيرُ",uz:"afsonalar uxlaydigan"}],full_uz:"Afsonalar uxlaydigan vodiylar orasida.",note:null},
{num:17,time:"00:01:10,340 --> 00:01:16,319",arabic:"وَبِحَارٍ تَهْمِسُ بِالْمِلْحِ وَالسَّكِينَةِ",segs:[{ar:"وَبِحَارٍ",uz:"va dengizlar orasida"},{ar:"تَهْمِسُ بِالْمِلْحِ وَالسَّكِينَةِ",uz:"tuz va sokinlik bilan shivirlaydigan"}],full_uz:"Tuz va sokinlik bilan shivirlaydigan dengizlar orasida.",note:null},
{num:18,time:"00:01:18,319 --> 00:01:23,319",arabic:"فِلَسْطِينُ الْوَجْهُ الْآخَرُ لِلْجَمَالِ وَلِلْدَّهْشَةِ وَلِلْحَيَاةِ",segs:[{ar:"فِلَسْطِينُ",uz:"Falastin"},{ar:"الْوَجْهُ الْآخَرُ لِلْجَمَالِ",uz:"go‘zallikning boshqa yuzi"},{ar:"وَلِلْدَّهْشَةِ وَلِلْحَيَاةِ",uz:"hayrat va hayotning ham"}],full_uz:"Falastin — go‘zallik, hayrat va hayotning boshqa yuzi.",note:null},
{num:19,time:"00:01:24,159 --> 00:01:32,500",arabic:"فِي قَلْبِ فِلَسْطِينِ تَنْهَضُ الْقُدْسُ مَدِينَةً لَا تُشْبِهُ غَيْرَهَا",segs:[{ar:"فِي قَلْبِ فِلَسْطِينِ",uz:"Falastin yuragida"},{ar:"تَنْهَضُ الْقُدْسُ",uz:"Quddus qad rostlaydi"},{ar:"مَدِينَةً لَا تُشْبِهُ غَيْرَهَا",uz:"boshqasiga o‘xshamaydigan shahar sifatida"}],full_uz:"Falastin yuragida boshqasiga o‘xshamaydigan shahar — Quddus qad rostlaydi.",note:"تَنْهَضُ — qad rostlamoq."},
{num:20,time:"00:01:32,500 --> 00:01:36,500",arabic:"فَهِيَ لَا تُبْنَى بِالْحِجَارَةِ بَلْ بِالصَّلَوَاتِ",segs:[{ar:"فَهِيَ لَا تُبْنَى بِالْحِجَارَةِ",uz:"chunki u toshlar bilan qurilmaydi"},{ar:"بَلْ بِالصَّلَوَاتِ",uz:"balki ibodatlar bilan"}],full_uz:"Chunki u toshlar bilan emas, balki ibodatlar bilan quriladi.",note:null},
{num:21,time:"00:01:36,500 --> 00:01:41,219",arabic:"وَلَا تُقَاسُ بِالشَّوَارِعِ بَلْ بِالنَّبْضِ الَّذِي يَسْكُنُهَا",segs:[{ar:"وَلَا تُقَاسُ بِالشَّوَارِعِ",uz:"va ko‘chalari bilan o‘lchanmaydi"},{ar:"بَلْ بِالنَّبْضِ الَّذِي يَسْكُنُهَا",uz:"balki unda yashovchi jo‘shqinlik bilan"}],full_uz:"Va ko‘chalari bilan emas, balki unda yashovchi jo‘shqinlik bilan o‘lchanadi.",note:"يَسْكُنُهَا — unda yashaydi."},
{num:22,time:"00:01:41,219 --> 00:01:47,359",arabic:"الْقُدْسُ لَيْسَتْ فَقَطْ مَآذِنَ وَقِبَابًا",segs:[{ar:"الْقُدْسُ لَيْسَتْ فَقَطْ",uz:"Quddus faqat"},{ar:"مَآذِنَ وَقِبَابًا",uz:"minoralar va gumbazlar emas"}],full_uz:"Quddus faqat minoralar va gumbazlardan iborat emas.",note:null},
{num:23,time:"00:01:47,359 --> 00:01:51,099",arabic:"بَلْ ذَاكِرَةٌ تَمْشِي فَوْقَ بِلَاطٍ مُقَدَّسٍ",segs:[{ar:"بَلْ ذَاكِرَةٌ",uz:"balki xotiradir"},{ar:"تَمْشِي فَوْقَ بِلَاطٍ مُقَدَّسٍ",uz:"muqaddas yo‘laklar ustida yuradigan"}],full_uz:"Balki muqaddas yo‘laklar ustida yuradigan xotiradir.",note:"بِلَاطٌ — plitka, tosh qoplama."},
{num:24,time:"00:01:51,099 --> 00:01:55,739",arabic:"وَكُلُّ حَجَرٍ فِيهَا شَاهِدٌ عَلَى أَلْفِ قِصَّةٍ",segs:[{ar:"وَكُلُّ حَجَرٍ فِيهَا",uz:"undagi har bir tosh"},{ar:"شَاهِدٌ عَلَى أَلْفِ قِصَّةٍ",uz:"minglab hikoyalarga guvoh"}],full_uz:"Undagi har bir tosh minglab hikoyalarga guvoh.",note:null},
{num:25,time:"00:01:55,739 --> 00:02:00,799",arabic:"هُنَا يُعَانِقُ الْمَسْجِدُ الْأَقْصَى قُبَّةَ الصَّخْرَةِ",segs:[{ar:"هُنَا يُعَانِقُ الْمَسْجِدُ الْأَقْصَى",uz:"bu yerda Al-Aqso masjidi quchoqlaydi"},{ar:"قُبَّةَ الصَّخْرَةِ",uz:"Qubbat as-Saxrani"}],full_uz:"Bu yerda Al-Aqso masjidi Qubbat as-Saxrani quchoqlab turadi.",note:"يُعَانِقُ — quchoqlamoq."},
{num:26,time:"00:02:00,799 --> 00:02:06,859",arabic:"وَتَلْتَقِي السَّمَاءُ بِأَرْضٍ ارْتَفَعَ مِنْهَا الْأَنْبِيَاءُ",segs:[{ar:"وَتَلْتَقِي السَّمَاءُ بِأَرْضٍ",uz:"osmon yer bilan uchrashadi"},{ar:"ارْتَفَعَ مِنْهَا الْأَنْبِيَاءُ",uz:"undan payg‘ambarlar yuksalgan"}],full_uz:"Osmon undan payg‘ambarlar yuksalgan yer bilan uchrashadi.",note:"ارْتَفَعَ — ko‘tarilmoq, yuksalmoq."},
{num:27,time:"00:02:06,859 --> 00:02:11,959",arabic:"حِينَ تَمْشِي فِي أَزِقَّةِ الْبَلْدَةِ الْقَدِيمَةِ",segs:[{ar:"حِينَ تَمْشِي",uz:"yurganingizda"},{ar:"فِي أَزِقَّةِ الْبَلْدَةِ الْقَدِيمَةِ",uz:"Eski shahar tor ko‘chalarida"}],full_uz:"Eski shaharning tor ko‘chalarida yurganingizda.",note:"أَزِقَّةٌ — tor ko‘chalar."},
{num:28,time:"00:02:11,959 --> 00:02:15,319",arabic:"تَشْعُرُ أَنَّ الزَّمَنَ قَدْ تَوَقَّفَ لِبُرْهَةٍ",segs:[{ar:"تَشْعُرُ أَنَّ الزَّمَنَ",uz:"zamon ... ekanini his qilasiz"},{ar:"قَدْ تَوَقَّفَ لِبُرْهَةٍ",uz:"bir lahzaga to‘xtab qolgan"}],full_uz:"Zamon bir lahzaga to‘xtab qolgandek his qilasiz.",note:"بُرْهَةٌ — qisqa lahza."},
{num:29,time:"00:02:15,319 --> 00:02:19,599",arabic:"لِيَمْنَحَكَ فُرْصَةً أَنْ تَلْمَسَ التَّارِيخَ بِيَدَيْكَ",segs:[{ar:"لِيَمْنَحَكَ فُرْصَةً",uz:"sizga imkon berish uchun"},{ar:"أَنْ تَلْمَسَ التَّارِيخَ بِيَدَيْكَ",uz:"tarixga o‘z qo‘llaringiz bilan tegishga"}],full_uz:"Tarixga o‘z qo‘llaringiz bilan tegishingiz uchun sizga imkon berish uchun.",note:"مَنَحَ — bermoq, ato etmoq."},
{num:30,time:"00:02:19,599 --> 00:02:44,519",arabic:"رَائِحَةُ الْخُبْزِ، نِدَاءُ الْبَاعَةِ، صَلَوَاتُ الْعَابِرِينَ، كُلُّهَا تُشَكِّلُ سِيمْفُونِيَّةَ مَدِينَةٍ تَنْبِضُ بِالْحَيَاةِ رَغْمَ كُلِّ شَيْءٍ، الْقُدْسُ لَيْسَتْ فَقَطْ حَاضِرَةَ الْمَاضِي، بَلْ نُبُوءَةَ الْمُسْتَقْبَلِ، مَدِينَةٌ تَأْبَى أَنْ تَنْكَسِرَ، وَكُلُّ صَبَاحٍ فِيهَا انْتِصَارٌ جَدِيدٌ لِلضَّوْءِ",segs:[{ar:"رَائِحَةُ الْخُبْزِ، نِدَاءُ الْبَاعَةِ، صَلَوَاتُ الْعَابِرِينَ",uz:"non hidi, sotuvchilarning nidosi va o‘tkinchilarning ibodatlari"},{ar:"كُلُّهَا تُشَكِّلُ سِيمْفُونِيَّةَ مَدِينَةٍ",uz:"barchasi bir shaharning simfoniyasini hosil qiladi"},{ar:"تَنْبِضُ بِالْحَيَاةِ رَغْمَ كُلِّ شَيْءٍ",uz:"barcha narsaga qaramay hayot bilan jo‘sh uradigan"},{ar:"الْقُدْسُ لَيْسَتْ فَقَطْ حَاضِرَةَ الْمَاضِي",uz:"Quddus faqat o‘tmishning hozirligi emas"},{ar:"بَلْ نُبُوءَةَ الْمُسْتَقْبَلِ",uz:"balki kelajak bashoratidir"},{ar:"مَدِينَةٌ تَأْبَى أَنْ تَنْكَسِرَ",uz:"sinishni rad etadigan shahar"},{ar:"وَكُلُّ صَبَاحٍ فِيهَا انْتِصَارٌ جَدِيدٌ لِلضَّوْءِ",uz:"va undagi har bir tong yorug‘likning yangi g‘alabasidir"}],full_uz:"Non hidi, sotuvchilarning nidosi va o‘tkinchilarning ibodatlari — barchasi barcha narsaga qaramay hayot bilan jo‘sh uradigan shaharning simfoniyasini hosil qiladi. Quddus faqat o‘tmishning hozirligi emas, balki kelajak bashoratidir; sinishni rad etadigan shahar va undagi har bir tong yorug‘likning yangi g‘alabasidir.",note:"تَأْبَى — rad etmoq, bosh tortmoq. نُبُوءَةٌ — bashorat."},
{num:31,time:"00:02:44,520 --> 00:02:52,980",arabic:"هُنَاكَ فِي أَقْصَى الْجَنُوبِ تَغْفُو أَعْجُوبَةٌ جِيُولُوجِيَّةٌ لَا مَثِيلَ لَهَا",segs:[{ar:"هُنَاكَ فِي أَقْصَى الْجَنُوبِ",uz:"u yerda, eng janubda"},{ar:"تَغْفُو أَعْجُوبَةٌ جِيُولُوجِيَّةٌ",uz:"geologik mo‘jiza uyquda yotadi"},{ar:"لَا مَثِيلَ لَهَا",uz:"unga o‘xshashi yo‘q"}],full_uz:"U yerda, eng janubda o‘xshashi yo‘q geologik mo‘jiza uyquda yotadi.",note:"تَغْفُو — mudramoq, uyquda yotmoq."},
{num:32,time:"00:02:52,980 --> 00:02:55,000",arabic:"الْبَحْرُ الْمَيِّتُ",segs:null,full_uz:"O‘lik dengiz.",note:null},
{num:33,time:"00:02:55,000 --> 00:03:03,780",arabic:"أَخْفَضُ نُقْطَةٍ عَلَى وَجْهِ الْأَرْضِ حَيْثُ تَنْزِلُ قَدَمَاكَ إِلَى عُمْقٍ لَا تَرَاهُ",segs:[{ar:"أَخْفَضُ نُقْطَةٍ عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzidagi eng past nuqta"},{ar:"حَيْثُ تَنْزِلُ قَدَمَاكَ",uz:"u yerda oyoqlaringiz tushadi"},{ar:"إِلَى عُمْقٍ لَا تَرَاهُ",uz:"ko‘ra olmaydigan chuqurlikka"}],full_uz:"Yer yuzidagi eng past nuqta, u yerda oyoqlaringiz ko‘ra olmaydigan chuqurlikka tushadi.",note:"أَخْفَضُ — eng past."},
{num:34,time:"00:03:03,780 --> 00:03:06,740",arabic:"لَكِنَّكَ تَشْعُرُ بِهِ فِي رُوحِكَ",segs:[{ar:"لَكِنَّكَ تَشْعُرُ بِهِ",uz:"ammo uni his qilasiz"},{ar:"فِي رُوحِكَ",uz:"ruhingizda"}],full_uz:"Ammo uni ruhingizda his qilasiz.",note:null},
{num:35,time:"00:03:06,740 --> 00:03:10,540",arabic:"هُنَا لَا تَغْرَقُ الْأَجْسَادُ",segs:null,full_uz:"Bu yerda jismlar cho‘kmaydi.",note:null},
{num:36,time:"00:03:10,540 --> 00:03:15,379",arabic:"بَلْ تَطْفُو كَأَنَّ الْمَاءَ يُعِيدُ لَهَا خِفَّةَ الْوُجُودِ",segs:[{ar:"بَلْ تَطْفُو",uz:"balki suzib turadi"},{ar:"كَأَنَّ الْمَاءَ يُعِيدُ لَهَا",uz:"go‘yo suv unga qaytarayotgandek"},{ar:"خِفَّةَ الْوُجُودِ",uz:"mavjudlik yengilligini"}],full_uz:"Balki suzib turadi, go‘yo suv unga mavjudlikning yengilligini qaytarayotgandek.",note:"تَطْفُو — suv yuzida suzmoq."},
{num:37,time:"00:03:15,379 --> 00:03:20,719",arabic:"إِنَّهُ مَكَانٌ يَقِفُ فِيهِ الزَّمَنُ",segs:[{ar:"إِنَّهُ مَكَانٌ",uz:"bu bir joy"},{ar:"يَقِفُ فِيهِ الزَّمَنُ",uz:"unda zamon to‘xtab qoladi"}],full_uz:"Bu zamon to‘xtab qolgandek bo‘ladigan joy.",note:null},
{num:38,time:"00:03:20,719 --> 00:03:25,960",arabic:"وَتَنْحَسِرُ فِيهِ الْحَيَاةُ لِتَكْشِفَ لَكَ عَنْ أَسْرَارِ الْأَرْضِ الْقَدِيمَةِ",segs:[{ar:"وَتَنْحَسِرُ فِيهِ الْحَيَاةُ",uz:"unda hayot chekinadi"},{ar:"لِتَكْشِفَ لَكَ",uz:"sizga ochib berish uchun"},{ar:"عَنْ أَسْرَارِ الْأَرْضِ الْقَدِيمَةِ",uz:"qadimiy yer sirlarini"}],full_uz:"Unda hayot chekinib, sizga qadimiy yer sirlarini ochib beradi.",note:"تَنْحَسِرُ — chekinmoq, kamaymoq."},
{num:39,time:"00:03:29,320 --> 00:03:32,980",arabic:"أَمْلَاحُهُ الْبَيْضَاءُ الْمُتَبَلْوِرَةُ كَالْكِرِسْتَالِ",segs:[{ar:"أَمْلَاحُهُ الْبَيْضَاءُ",uz:"uning oq tuzlari"},{ar:"الْمُتَبَلْوِرَةُ كَالْكِرِسْتَالِ",uz:"billur kabi kristallangan"}],full_uz:"Uning billur kabi kristallangan oq tuzlari.",note:"مُتَبَلْوِرٌ — kristallangan."},
{num:40,time:"00:03:32,980 --> 00:03:36,080",arabic:"تَكْسُو الشَّوَاطِئَ بِهُدُوءٍ مَهِيبٍ",segs:null,full_uz:"Qirg‘oqlarni haybatli sokinlik bilan qoplaydi.",note:"تَكْسُو — qoplamoq, ustini qoplab turmoq."},
{num:41,time:"00:03:36,080 --> 00:03:41,460",arabic:"تَبْدُو كَأَنَّهَا آثَارُ حَضَارَةٍ بَحْرِيَّةٍ قَدِيمَةٍ انْدَثَرَتْ",segs:[{ar:"تَبْدُو كَأَنَّهَا آثَارُ حَضَارَةٍ بَحْرِيَّةٍ قَدِيمَةٍ",uz:"go‘yo qadimiy dengiz sivilizatsiyasining qoldiqlaridek ko‘rinadi"},{ar:"انْدَثَرَتْ",uz:"yo‘q bo‘lib ketgan"}],full_uz:"Go‘yo yo‘q bo‘lib ketgan qadimiy dengiz sivilizatsiyasining qoldiqlaridek ko‘rinadi.",note:"انْدَثَرَ — yo‘q bo‘lmoq, izsiz ketmoq."},
{num:42,time:"00:03:41,460 --> 00:03:46,800",arabic:"لَكِنَّهَا مَا زَالَتْ تَهْمِسُ فِي أُذُنِكَ بِحِكَايَاتِهَا",segs:[{ar:"لَكِنَّهَا مَا زَالَتْ تَهْمِسُ",uz:"ammo u hamon shivirlaydi"},{ar:"فِي أُذُنِكَ بِحِكَايَاتِهَا",uz:"qulog‘ingizga o‘z hikoyalarini"}],full_uz:"Ammo u hamon o‘z hikoyalarini qulog‘ingizga shivirlaydi.",note:null},
{num:43,time:"00:03:46,800 --> 00:03:52,680",arabic:"وَتِلْكَ الْجِبَالُ الْمُحِيطَةُ",segs:null,full_uz:"Va o‘sha atrofdagi tog‘lar.",note:null},
{num:44,time:"00:03:52,680 --> 00:03:56,340",arabic:"بِأَلْوَانِهَا الْقِرْمِزِيَّةِ وَظِلَالِهَا الصَّامِتَةِ",segs:[{ar:"بِأَلْوَانِهَا الْقِرْمِزِيَّةِ",uz:"qirmizi ranglari bilan"},{ar:"وَظِلَالِهَا الصَّامِتَةِ",uz:"va sokin soyalari bilan"}],full_uz:"Qirmizi ranglari va sokin soyalari bilan.",note:"قِرْمِزِيٌّ — qirmizi, to‘q qizil."},
{num:45,time:"00:03:56,340 --> 00:03:59,960",arabic:"تَشْهَدُ عَلَى تَوَازُنٍ بَيْنَ الْمَوْتِ وَالْحَيَاةِ",segs:[{ar:"تَشْهَدُ عَلَى تَوَازُنٍ",uz:"muvozanatga guvoh bo‘ladi"},{ar:"بَيْنَ الْمَوْتِ وَالْحَيَاةِ",uz:"o‘lim va hayot o‘rtasidagi"}],full_uz:"O‘lim va hayot o‘rtasidagi muvozanatga guvoh bo‘ladi.",note:"تَوَازُنٌ — muvozanat."},
{num:46,time:"00:03:59,960 --> 00:04:02,060",arabic:"بَيْنَ الصَّمْتِ وَالْخُلُودِ",segs:null,full_uz:"Sukunat va abadiylik o‘rtasida.",note:null},
{num:47,time:"00:04:02,060 --> 00:04:05,800",arabic:"الْبَحْرُ الْمَيِّتُ",segs:null,full_uz:"O‘lik dengiz.",note:null},
{num:48,time:"00:04:05,800 --> 00:04:10,300",arabic:"لَيْسَ فَقَطْ مَكَانًا، بَلْ تَجْرِبَةٌ رُوحِيَّةٌ",segs:[{ar:"لَيْسَ فَقَطْ مَكَانًا",uz:"shunchaki joy emas"},{ar:"بَلْ تَجْرِبَةٌ رُوحِيَّةٌ",uz:"balki ruhiy tajriba"}],full_uz:"Shunchaki joy emas, balki ruhiy tajriba.",note:"تَجْرِبَةٌ رُوحِيَّةٌ — ruhiy tajriba."},
{num:49,time:"00:04:10,300 --> 00:04:16,360",arabic:"تُعَلِّمُكَ أَنَّ أَعْمَقَ الْأَمَاكِنِ قَدْ تَكُونُ أَكْثَرَهَا هُدُوءًا",segs:[{ar:"تُعَلِّمُكَ",uz:"sizga o‘rgatadi"},{ar:"أَنَّ أَعْمَقَ الْأَمَاكِنِ",uz:"eng chuqur joylar"},{ar:"قَدْ تَكُونُ أَكْثَرَهَا هُدُوءًا",uz:"eng sokin joylar bo‘lishi mumkinligini"}],full_uz:"Eng chuqur joylar eng sokin joylar bo‘lishi mumkinligini o‘rgatadi.",note:null},
{num:50,time:"00:04:16,360 --> 00:04:21,560",arabic:"هُنَاكَ، فِي قَلْبِ فِلَسْطِينِ",segs:null,full_uz:"U yerda, Falastin yuragida.",note:null},
{num:51,time:"00:04:21,560 --> 00:04:25,199",arabic:"وَعِنْدَ السُّفُوحِ الدَّافِئَةِ لِوَادِي نَهْرِ الْأُرْدُنِّ",segs:[{ar:"وَعِنْدَ السُّفُوحِ الدَّافِئَةِ",uz:"iliq etaklarda"},{ar:"لِوَادِي نَهْرِ الْأُرْدُنِّ",uz:"Iordaniya daryosi vodiysining"}],full_uz:"Iordaniya daryosi vodiysining iliq etaklarida.",note:"سُفُوحٌ — tog‘ etaklari, yonbag‘irlar."},
{num:52,time:"00:04:25,199 --> 00:04:30,259",arabic:"تَقَعُ أَرِيحَا، أَقْدَمُ مَدِينَةٍ مَأْهُولَةٍ فِي التَّارِيخِ",segs:[{ar:"تَقَعُ أَرِيحَا",uz:"Yerixo joylashgan"},{ar:"أَقْدَمُ مَدِينَةٍ مَأْهُولَةٍ فِي التَّارِيخِ",uz:"tarixdagi eng qadimiy yashash davom etayotgan shahar"}],full_uz:"Tarixdagi eng qadimiy doimiy yashab kelinayotgan shahar — Yerixo joylashgan.",note:"مَأْهُولٌ — aholi yashaydigan."},
{num:53,time:"00:04:30,259 --> 00:04:33,939",arabic:"حَيْثُ تَنْحَنِي الْقُرُونُ أَمَامَ عَبَقِ الْحَضَارَاتِ",segs:[{ar:"حَيْثُ تَنْحَنِي الْقُرُونُ",uz:"u yerda asrlar bosh egadi"},{ar:"أَمَامَ عَبَقِ الْحَضَارَاتِ",uz:"sivilizatsiyalar ifori qarshisida"}],full_uz:"U yerda asrlar sivilizatsiyalar ifori qarshisida bosh egadi.",note:"عَبَقٌ — ifor, kuchli hid."},
{num:54,time:"00:04:33,939 --> 00:04:42,439",arabic:"أَرِيحَا لَيْسَتْ فَقَطْ مَدِينَةً بَلْ قَصِيدَةٌ كَتَبَتْهَا الشَّمْسُ عَلَى أَرْضِ فِلَسْطِينِ",segs:[{ar:"أَرِيحَا لَيْسَتْ فَقَطْ مَدِينَةً",uz:"Yerixo shunchaki shahar emas"},{ar:"بَلْ قَصِيدَةٌ",uz:"balki she’r"},{ar:"كَتَبَتْهَا الشَّمْسُ عَلَى أَرْضِ فِلَسْطِينِ",uz:"uni quyosh Falastin yeriga yozgan"}],full_uz:"Yerixo shunchaki shahar emas, balki quyosh Falastin yeriga yozgan she’rdir.",note:null},
{num:55,time:"00:04:42,439 --> 00:04:46,259",arabic:"مَدِينَةٌ لَا تَزَالُ تَنْبِضُ بِالْحَيَاةِ",segs:[{ar:"مَدِينَةٌ",uz:"bir shahar"},{ar:"لَا تَزَالُ تَنْبِضُ بِالْحَيَاةِ",uz:"hamon hayot bilan jo‘sh uradigan"}],full_uz:"Hamon hayot bilan jo‘sh uradigan shahar.",note:null},
{num:56,time:"00:04:46,259 --> 00:04:51,699",arabic:"رَغْمَ أَنَّ عُمْرَهَا يَمْتَدُّ لِأَكْثَرَ مِنْ عَشَرَةِ آلَافِ عَامٍ",segs:[{ar:"رَغْمَ أَنَّ عُمْرَهَا يَمْتَدُّ",uz:"uning yoshi cho‘zilib kelayotgan bo‘lsa-da"},{ar:"لِأَكْثَرَ مِنْ عَشَرَةِ آلَافِ عَامٍ",uz:"o‘n ming yildan ortiq"}],full_uz:"Uning yoshi o‘n ming yildan ortiq bo‘lsa-da.",note:null},
{num:57,time:"00:04:51,699 --> 00:04:58,980",arabic:"فِي تَلِّ السُّلْطَانِ تَتَنَاثَرُ آثَارُ حَضَارَاتٍ مَرَّتْ مِنْ هُنَا",segs:[{ar:"فِي تَلِّ السُّلْطَانِ",uz:"Tell as-Sultonda"},{ar:"تَتَنَاثَرُ آثَارُ حَضَارَاتٍ",uz:"sivilizatsiyalar qoldiqlari sochilib yotadi"},{ar:"مَرَّتْ مِنْ هُنَا",uz:"bu yerdan o‘tgan"}],full_uz:"Tell as-Sultonda bu yerdan o‘tgan sivilizatsiyalarning qoldiqlari sochilib yotadi.",note:"آثَارٌ — qoldiqlar, izlar."},
{num:58,time:"00:04:58,980 --> 00:05:03,160",arabic:"جُدْرَانٌ، أَبْرَاجٌ، وَأَدْرَاجٌ حَجَرِيَّةٌ",segs:null,full_uz:"Devorlar, minoralar va tosh zinapoyalar.",note:"أَدْرَاجٌ — zinapoyalar."},
{num:59,time:"00:05:03,160 --> 00:05:07,980",arabic:"كُلُّهَا تَشْهَدُ عَلَى إِنْسَانٍ بَدَأَ الْحِكَايَةَ مِنْ هَذَا التُّرَابِ",segs:[{ar:"كُلُّهَا تَشْهَدُ",uz:"ularning barchasi guvohlik beradi"},{ar:"عَلَى إِنْسَانٍ بَدَأَ الْحِكَايَةَ",uz:"hikoyani boshlagan inson haqida"},{ar:"مِنْ هَذَا التُّرَابِ",uz:"shu tuproqdan"}],full_uz:"Ularning barchasi hikoyani shu tuproqdan boshlagan inson haqida guvohlik beradi.",note:null},
{num:60,time:"00:05:07,980 --> 00:05:14,100",arabic:"وَعَيْنُ السُّلْطَانِ الَّتِي لَا تَزَالُ تَتَدَفَّقُ مُنْذُ الْعُصُورِ الْأُولَى",segs:[{ar:"وَعَيْنُ السُّلْطَانِ",uz:"va Sulton bulog‘i"},{ar:"الَّتِي لَا تَزَالُ تَتَدَفَّقُ",uz:"hamon oqib turadigan"},{ar:"مُنْذُ الْعُصُورِ الْأُولَى",uz:"qadimgi davrlardan beri"}],full_uz:"Va qadimgi davrlardan beri hamon oqib turgan Sulton bulog‘i.",note:"عَيْنٌ — buloq, chashma."},
{num:61,time:"00:05:14,100 --> 00:05:16,460",arabic:"تَسْقِي النَّخِيلَ وَالْبُرْتُقَالَ",segs:null,full_uz:"Xurmo va apelsin daraxtlarini sug‘oradi.",note:"تَسْقِي — sug‘ormoq."},
{num:62,time:"00:05:16,460 --> 00:05:21,819",arabic:"وَتَرْوِي قِصَّةَ مَدِينَةٍ تَحَدَّتِ الْعُصُورَ وَالْجَفَافَ وَالنِّسْيَانَ",segs:[{ar:"وَتَرْوِي قِصَّةَ مَدِينَةٍ",uz:"va bir shahar haqida hikoya qiladi"},{ar:"تَحَدَّتِ الْعُصُورَ وَالْجَفَافَ وَالنِّسْيَانَ",uz:"asrlar, qurg‘oqchilik va unutilishga qarshi turgan"}],full_uz:"Va asrlar, qurg‘oqchilik va unutilishga qarshi turgan shahar haqida hikoya qiladi.",note:"تَحَدَّى — qarshi turmoq, bo‘ysunmaslik."},
{num:63,time:"00:05:21,819 --> 00:05:26,080",arabic:"وَتَحْتَ وَهَجِ الشَّمْسِ الْفِلَسْطِينِيَّةِ",segs:null,full_uz:"Va Falastin quyoshining yog‘dusi ostida.",note:"وَهَجٌ — yog‘du, kuchli nur."},
{num:64,time:"00:05:26,079 --> 00:05:29,319",arabic:"تَسْتَرِيحُ أَرِيحَا كَوَاحَةٍ مِنْ هُدُوءٍ",segs:[{ar:"تَسْتَرِيحُ أَرِيحَا",uz:"Yerixo orom oladi"},{ar:"كَوَاحَةٍ مِنْ هُدُوءٍ",uz:"sokinlik vohasidek"}],full_uz:"Yerixo sokinlik vohasidek orom oladi.",note:"وَاحَةٌ — voha."},
{num:65,time:"00:05:29,319 --> 00:05:35,219",arabic:"تُغَنِّي أُغْنِيَةً قَدِيمَةً لَا يَعْرِفُهَا إِلَّا مَنْ أَرْهَفَ قَلْبَهُ لِلتَّارِيخِ",segs:[{ar:"تُغَنِّي أُغْنِيَةً قَدِيمَةً",uz:"qadimiy qo‘shiq kuylaydi"},{ar:"لَا يَعْرِفُهَا إِلَّا مَنْ أَرْهَفَ قَلْبَهُ لِلتَّارِيخِ",uz:"uni faqat tarixga qalbini ochgan kishi biladi"}],full_uz:"U faqat tarixga qalbini ochgan kishi biladigan qadimiy qo‘shiqni kuylaydi.",note:"أَرْهَفَ قَلْبَهُ — qalbini nozik sezishga ochmoq."},
{num:66,time:"00:05:35,219 --> 00:05:37,959",arabic:"أَرِيحَا",segs:null,full_uz:"Yerixo.",note:null},
{num:67,time:"00:05:37,959 --> 00:05:40,360",arabic:"هُنَا بَدَأَتِ الْحَضَارَةُ",segs:null,full_uz:"Bu yerda sivilizatsiya boshlandi.",note:null},
{num:68,time:"00:05:40,360 --> 00:05:43,459",arabic:"وَمِنْ هُنَا مَا زَالَتْ فِلَسْطِينُ تَكْتُبُ",segs:[{ar:"وَمِنْ هُنَا",uz:"va shu yerdan"},{ar:"مَا زَالَتْ فِلَسْطِينُ تَكْتُبُ",uz:"Falastin hamon yozib kelmoqda"}],full_uz:"Va shu yerdan Falastin hamon yozib kelmoqda.",note:"مَا زَالَ — hamon, hanuz davom etmoqda."},
{num:69,time:"00:05:43,459 --> 00:05:48,039",arabic:"فِي قَلْبِ الضِّفَّةِ الْغَرْبِيَّةِ",segs:null,full_uz:"G‘arbiy Sohilning qalbida.",note:null},
{num:70,time:"00:05:48,039 --> 00:05:51,319",arabic:"وَبَيْنَ طَيَّاتِ الْجِبَالِ الْمُتَعَرِّجَةِ",segs:null,full_uz:"Va egri-bugri tog‘lar bag‘rida.",note:"طَيَّاتٌ — qatlamlar, bag‘irlar."},
{num:71,time:"00:05:51,319 --> 00:05:52,879",arabic:"شَرْقَ رَامَ اللَّهِ",segs:null,full_uz:"Ramalloh sharqida.",note:null},
{num:72,time:"00:05:52,879 --> 00:05:56,279",arabic:"يَنْسَابُ وَادِي الْقَلْطِ كَخَيْطٍ مِنَ النُّورِ",segs:[{ar:"يَنْسَابُ وَادِي الْقَلْطِ",uz:"Qilt vodiysi oqib yotadi"},{ar:"كَخَيْطٍ مِنَ النُّورِ",uz:"nur ipidek"}],full_uz:"Qilt vodiysi nur ipidek oqib yotadi.",note:"يَنْسَابُ — ravon oqmoq, sirg‘alib oqmoq."},
{num:73,time:"00:05:56,279 --> 00:05:59,120",arabic:"يَمْزِجُ بَيْنَ الصَّخْرِ وَالْمَاءِ",segs:null,full_uz:"Tosh va suvni uyg‘unlashtiradi.",note:null},
{num:74,time:"00:05:59,120 --> 00:06:01,519",arabic:"بَيْنَ الْعُزْلَةِ وَالتَّأَمُّلِ",segs:null,full_uz:"Yolg‘izlik va tafakkur o‘rtasida.",note:"الْعُزْلَةُ — yolg‘izlik, chekinish."},
{num:75,time:"00:06:01,519 --> 00:06:08,480",arabic:"هُنَا يَخْتَرِقُ الْوَادِي الْأَرْضَ بِصَمْتٍ",segs:[{ar:"هُنَا يَخْتَرِقُ الْوَادِي الْأَرْضَ",uz:"bu yerda vodiy yer bag‘rini yorib o‘tadi"},{ar:"بِصَمْتٍ",uz:"sukunat bilan"}],full_uz:"Bu yerda vodiy yer bag‘rini sukunat bilan yorib o‘tadi.",note:"يَخْتَرِقُ — yorib o‘tmoq."},
{num:76,time:"00:06:08,480 --> 00:06:10,860",arabic:"تَتْبَعُهُ عَيْنُ الْقَلْطِ",segs:null,full_uz:"Uning ortidan Qilt bulog‘i keladi.",note:"تَتْبَعُ — ergashmoq, ortidan kelmoq. عَيْنٌ — buloq."},
{num:77,time:"00:06:10,860 --> 00:06:13,279",arabic:"عَيْنٌ بَارِدَةٌ رَقْرَاقَةٌ",segs:null,full_uz:"Sovuq, tiniq buloq.",note:"رَقْرَاقٌ — tiniq, jilvalanib oqadigan."},
{num:78,time:"00:06:13,279 --> 00:06:17,159",arabic:"تَنْسَابُ بَيْنَ الصُّخُورِ مُنْذُ آلَافِ السِّنِينَ",segs:[{ar:"تَنْسَابُ بَيْنَ الصُّخُورِ",uz:"qoyalar orasidan ravon oqadi"},{ar:"مُنْذُ آلَافِ السِّنِينَ",uz:"minglab yillardan beri"}],full_uz:"U minglab yillardan beri qoyalar orasidan ravon oqadi.",note:null},
{num:79,time:"00:06:17,159 --> 00:06:22,199",arabic:"تَسْقِي الْأَرْضَ وَتَهْمِسُ لِأَشْجَارِ النَّخِيلِ وَالزَّيْتُونِ",segs:[{ar:"تَسْقِي الْأَرْضَ",uz:"yerni sug‘oradi"},{ar:"وَتَهْمِسُ لِأَشْجَارِ النَّخِيلِ وَالزَّيْتُونِ",uz:"xurmo va zaytun daraxtlariga shivirlaydi"}],full_uz:"Yerni sug‘oradi va xurmo hamda zaytun daraxtlariga shivirlaydi.",note:null},
{num:80,time:"00:06:22,199 --> 00:06:27,819",arabic:"عَلَى حَوَافِّ الْوَادِي يَتَدَلَّى دَيْرُ الْقِدِّيسِ جُورْجِ",segs:[{ar:"عَلَى حَوَافِّ الْوَادِي",uz:"vodiy chekkalarida"},{ar:"يَتَدَلَّى دَيْرُ الْقِدِّيسِ جُورْجِ",uz:"Avliyo Georgiy monastiri osilib turadi"}],full_uz:"Vodiy chekkalarida Avliyo Georgiy monastiri osilib turadi.",note:"يَتَدَلَّى — osilib turmoq."},
{num:81,time:"00:06:27,819 --> 00:06:31,599",arabic:"مُعَلَّقًا كَمُعْجِزَةٍ بَيْنَ السَّمَاءِ وَالْأَرْضِ",segs:[{ar:"مُعَلَّقًا كَمُعْجِزَةٍ",uz:"mo‘jizadek osilib"},{ar:"بَيْنَ السَّمَاءِ وَالْأَرْضِ",uz:"yer bilan osmon orasida"}],full_uz:"Yer bilan osmon orasida mo‘jizadek osilib turadi.",note:"مُعَلَّقٌ — osilgan, muallaq."},
{num:82,time:"00:06:31,599 --> 00:06:37,599",arabic:"بُنِيَ عَلَى جُرْفٍ صَخْرِيٍّ وَكَأَنَّهُ يُرَاقِبُ الزَّمَنَ دُونَ أَنْ يَخْضَعَ لَهُ",segs:[{ar:"بُنِيَ عَلَى جُرْفٍ صَخْرِيٍّ",uz:"qoyali jarlik ustiga qurilgan"},{ar:"وَكَأَنَّهُ يُرَاقِبُ الزَّمَنَ",uz:"go‘yo zamonni kuzatib turgandek"},{ar:"دُونَ أَنْ يَخْضَعَ لَهُ",uz:"unga bo‘ysunmasdan"}],full_uz:"U qoyali jarlik ustiga qurilgan, go‘yo zamonni unga bo‘ysunmay kuzatib turgandek.",note:"جُرْفٌ — tik jarlik. يَخْضَعُ — bo‘ysunmoq."},
{num:83,time:"00:06:37,599 --> 00:06:45,079",arabic:"هُنَا لَا تَسْمَعُ سِوَى صَوْتِ الْمَاءِ وَخَرِيرِ الْجَدَاوِلِ",segs:[{ar:"هُنَا لَا تَسْمَعُ سِوَى",uz:"bu yerda faqat eshitasiz"},{ar:"صَوْتِ الْمَاءِ وَخَرِيرِ الْجَدَاوِلِ",uz:"suv ovozi va soylarning shildirashini"}],full_uz:"Bu yerda faqat suv ovozi va soylarning shildirashini eshitasiz.",note:"خَرِيرٌ — suvning shildirashi."},
{num:84,time:"00:06:45,079 --> 00:06:49,180",arabic:"وَتَغْرِيدَ الطُّيُورِ الَّتِي اتَّخَذَتْ مِنَ الْعُزْلَةِ وَطَنًا",segs:[{ar:"وَتَغْرِيدَ الطُّيُورِ",uz:"va qushlarning sayrashini"},{ar:"الَّتِي اتَّخَذَتْ مِنَ الْعُزْلَةِ وَطَنًا",uz:"yolg‘izlikni vatan qilgan"}],full_uz:"Va yolg‘izlikni vatan qilgan qushlarning sayrashini.",note:"اتَّخَذَ — ... qilib oldi."},
{num:85,time:"00:06:49,180 --> 00:06:58,040",arabic:"وَادِي الْقَلْطِ لَيْسَ فَقَطْ مَكَانًا، بَلْ فُسْحَةٌ رُوحِيَّةٌ",segs:[{ar:"وَادِي الْقَلْطِ لَيْسَ فَقَطْ مَكَانًا",uz:"Qilt vodiysi shunchaki joy emas"},{ar:"بَلْ فُسْحَةٌ رُوحِيَّةٌ",uz:"balki ruhiy kenglikdir"}],full_uz:"Qilt vodiysi shunchaki joy emas, balki ruhiy kenglikdir.",note:"فُسْحَةٌ — kenglik, bo‘sh makon; bu yerda ruhiy orom maskani ma’nosida."},
{num:86,time:"00:06:58,040 --> 00:07:04,460",arabic:"حِينَ تَمْشِي فِي دُرُوبِهِ الضَّيِّقَةِ، تَشْعُرُ وَكَأَنَّكَ تَعُودُ إِلَى ذَاتِكَ",segs:[{ar:"حِينَ تَمْشِي فِي دُرُوبِهِ الضَّيِّقَةِ",uz:"uning tor yo‘llaridan yurganingizda"},{ar:"تَشْعُرُ وَكَأَنَّكَ تَعُودُ إِلَى ذَاتِكَ",uz:"go‘yo o‘zingizga qaytayotgandek his qilasiz"}],full_uz:"Uning tor yo‘llaridan yurganingizda, go‘yo o‘zingizga qaytayotgandek his qilasiz.",note:"دُرُوبٌ — yo‘llar, so‘qmoqlar."},
{num:87,time:"00:07:04,460 --> 00:07:10,000",arabic:"إِلَى سُكُونٍ نَادِرٍ لَمْ تَعُدْ تَرَاهُ فِي زِحَامِ هَذَا الْعَالَمِ",segs:[{ar:"إِلَى سُكُونٍ نَادِرٍ",uz:"noyob sokinlikka"},{ar:"لَمْ تَعُدْ تَرَاهُ فِي زِحَامِ هَذَا الْعَالَمِ",uz:"bu dunyoning gavjumligida endi ko‘rmaydigan"}],full_uz:"Bu dunyoning gavjumligida endi ko‘rinmaydigan noyob sokinlikka.",note:"زِحَامٌ — gavjumlik, tirbandlik."},
{num:88,time:"00:07:10,000 --> 00:07:18,340",arabic:"وَادِي الْقَلْطِ، وَاحَةٌ خَفِيَّةٌ مِنْ جَمَالٍ لَا يُقَالُ، بَلْ يُحَسُّ",segs:[{ar:"وَادِي الْقَلْطِ، وَاحَةٌ خَفِيَّةٌ",uz:"Qilt vodiysi yashirin bir voha"},{ar:"مِنْ جَمَالٍ لَا يُقَالُ",uz:"so‘z bilan aytib bo‘lmaydigan go‘zallikdan"},{ar:"بَلْ يُحَسُّ",uz:"balki his qilinadigan"}],full_uz:"Qilt vodiysi so‘z bilan aytib bo‘lmaydigan, balki his qilinadigan go‘zallikning yashirin vohasidir.",note:"خَفِيٌّ — yashirin."},
{num:89,time:"00:07:18,339 --> 00:07:25,459",arabic:"هُنَاكَ بَيْنَ التِّلَالِ الْهَادِئَةِ فِي الضِّفَّةِ الْغَرْبِيَّةِ",segs:[{ar:"هُنَاكَ بَيْنَ التِّلَالِ الْهَادِئَةِ",uz:"u yerda, sokin tepaliklar orasida"},{ar:"فِي الضِّفَّةِ الْغَرْبِيَّةِ",uz:"G‘arbiy Sohilda"}],full_uz:"U yerda, G‘arbiy Sohildagi sokin tepaliklar orasida.",note:null},
{num:90,time:"00:07:25,459 --> 00:07:29,439",arabic:"تَزْهَرُ بَيْتُ لَحْمٍ كَأَنَّهَا تَرْنِيمَةٌ قَدِيمَةٌ",segs:[{ar:"تَزْهَرُ بَيْتُ لَحْمٍ",uz:"Baytlahm yashnab turadi"},{ar:"كَأَنَّهَا تَرْنِيمَةٌ قَدِيمَةٌ",uz:"go‘yo qadimiy madhiyadek"}],full_uz:"Baytlahm go‘yo qadimiy madhiyadek yashnab turadi.",note:"تَرْنِيمَةٌ — madhiyа, ohangli qo‘shiq."},
{num:91,time:"00:07:29,439 --> 00:07:34,579",arabic:"مَدِينَةٌ صَغِيرَةٌ لَكِنْ وَقْعُهَا كَبِيرٌ فِي قُلُوبِ الْعَالَمِ",segs:[{ar:"مَدِينَةٌ صَغِيرَةٌ",uz:"kichik shahar"},{ar:"لَكِنْ وَقْعُهَا كَبِيرٌ",uz:"ammo uning ta’siri katta"},{ar:"فِي قُلُوبِ الْعَالَمِ",uz:"dunyo qalblarida"}],full_uz:"Kichik shahar, ammo uning dunyo qalblaridagi ta’siri katta.",note:"وَقْعٌ — ta’sir, taassurot."},
{num:92,time:"00:07:34,579 --> 00:07:42,639",arabic:"فِي شَوَارِعِهَا يَمْتَزِجُ عَبَقُ التَّارِيخِ بِرَائِحَةِ الزَّعْتَرِ وَالْخُبْزِ الطَّازَجِ",segs:[{ar:"فِي شَوَارِعِهَا",uz:"uning ko‘chalarida"},{ar:"يَمْتَزِجُ عَبَقُ التَّارِيخِ",uz:"tarix ifori qorishadi"},{ar:"بِرَائِحَةِ الزَّعْتَرِ وَالْخُبْزِ الطَّازَجِ",uz:"za’atar va yangi non hidiga"}],full_uz:"Uning ko‘chalarida tarix ifori za’atar va yangi non hidiga qorishadi.",note:"عَبَقٌ — ifor. الزَّعْتَرُ — za’atar."},
{num:93,time:"00:07:42,639 --> 00:07:46,979",arabic:"وَحِجَارَةُ بُيُوتِهَا تَحْكِي عَنْ أَزْمِنَةٍ مَضَتْ",segs:[{ar:"وَحِجَارَةُ بُيُوتِهَا",uz:"va uylarining toshlari"},{ar:"تَحْكِي عَنْ أَزْمِنَةٍ مَضَتْ",uz:"o‘tib ketgan davrlar haqida hikoya qiladi"}],full_uz:"Va uylarining toshlari o‘tib ketgan davrlar haqida hikoya qiladi.",note:null},
{num:94,time:"00:07:46,980 --> 00:07:48,980",arabic:"وَلَمْ تُنْسَ",segs:null,full_uz:"Va unutilmagan.",note:"تُنْسَ — unutilmoq."},
{num:95,time:"00:07:48,980 --> 00:07:52,400",arabic:"هِيَ مَهْدُ السَّيِّدِ الْمَسِيحِ",segs:[{ar:"هِيَ مَهْدُ",uz:"u beshikdir"},{ar:"السَّيِّدِ الْمَسِيحِ",uz:"Masih Hazratning"}],full_uz:"U Hazrat Masihning beshigi.",note:"مَهْدٌ — beshik."},
{num:96,time:"00:07:52,400 --> 00:07:57,819",arabic:"وَالْأَرْضُ الَّتِي تَتَقَاطَعُ فِيهَا الدِّيَانَاتُ وَالصَّلَوَاتُ وَالدُّمُوعُ",segs:[{ar:"وَالْأَرْضُ الَّتِي تَتَقَاطَعُ فِيهَا",uz:"va unda kesishadigan yurt"},{ar:"الدِّيَانَاتُ وَالصَّلَوَاتُ وَالدُّمُوعُ",uz:"dinlar, ibodatlar va ko‘z yoshlar"}],full_uz:"Dinlar, ibodatlar va ko‘z yoshlar kesishadigan yurt.",note:"تَتَقَاطَعُ — kesishmoq."},
{num:97,time:"00:07:57,819 --> 00:08:00,080",arabic:"كَنِيسَةُ الْمَهْدِ",segs:null,full_uz:"Tug‘ilish cherkovi.",note:null},
{num:98,time:"00:08:00,080 --> 00:08:03,640",arabic:"بِتِلْكَ الْأَعْمِدَةِ الْحَجَرِيَّةِ وَالصَّمْتِ الْمَهِيبِ",segs:[{ar:"بِتِلْكَ الْأَعْمِدَةِ الْحَجَرِيَّةِ",uz:"o‘sha tosh ustunlari bilan"},{ar:"وَالصَّمْتِ الْمَهِيبِ",uz:"va haybatli sukunati bilan"}],full_uz:"O‘sha tosh ustunlari va haybatli sukunati bilan.",note:null},
{num:99,time:"00:08:03,640 --> 00:08:06,180",arabic:"تَحْتَضِنُكَ بِهُدُوءٍ",segs:null,full_uz:"Sizni sokinlik bilan bag‘riga oladi.",note:null},
{num:100,time:"00:08:06,180 --> 00:08:10,120",arabic:"وَتَهْمِسُ فِي أُذُنِكَ أَنَّ السَّلَامَ لَيْسَ حُلْمًا",segs:[{ar:"وَتَهْمِسُ فِي أُذُنِكَ",uz:"qulog‘ingizga shivirlaydi"},{ar:"أَنَّ السَّلَامَ لَيْسَ حُلْمًا",uz:"tinchlik tush emasligini"}],full_uz:"Va qulog‘ingizga tinchlik tush emasligini shivirlaydi.",note:null},
{num:101,time:"00:08:10,120 --> 00:08:12,340",arabic:"بَلْ حَقًّا مَنْسِيًّا",segs:null,full_uz:"Balki unutilgan bir haqiqatdir.",note:"مَنْسِيٌّ — unutilgan."},
{num:102,time:"00:08:12,340 --> 00:08:14,920",arabic:"فِي الْأَزِقَّةِ الْقَدِيمَةِ",segs:null,full_uz:"Qadimiy tor ko‘chalarda.",note:null},
{num:103,time:"00:08:14,920 --> 00:08:18,000",arabic:"تَجُولُ خُطُوَاتُ الزُّوَّارِ وَالْحُجَّاجِ",segs:[{ar:"تَجُولُ خُطُوَاتُ الزُّوَّارِ",uz:"ziyoratchilarning qadamlari kezadi"},{ar:"وَالْحُجَّاجِ",uz:"va hojilarning"}],full_uz:"Ziyoratchilar va hojilarning qadamlari kezadi.",note:"تَجُولُ — kezib yurmoq."},
{num:104,time:"00:08:18,000 --> 00:08:21,560",arabic:"تُشْعِلُ شَمْعَةً وَتَلْتَقِطُ صُورَةً",segs:[{ar:"تُشْعِلُ شَمْعَةً",uz:"sham yoqadi"},{ar:"وَتَلْتَقِطُ صُورَةً",uz:"va suratga oladi"}],full_uz:"Sham yoqadi va suratga oladi.",note:"أَشْعَلَ — yoqmoq."},
{num:105,time:"00:08:21,560 --> 00:08:25,699",arabic:"ثُمَّ تَمْضِي وَهِيَ تَتْرُكُ جُزْءًا مِنْ قَلْبِهَا خَلْفَهَا",segs:[{ar:"ثُمَّ تَمْضِي",uz:"so‘ng ketadi"},{ar:"وَهِيَ تَتْرُكُ جُزْءًا مِنْ قَلْبِهَا",uz:"qalbining bir qismini qoldirib"},{ar:"خَلْفَهَا",uz:"ortida"}],full_uz:"So‘ng qalbining bir qismini ortida qoldirib ketadi.",note:null},
{num:106,time:"00:08:25,699 --> 00:08:30,480",arabic:"رَغْمَ الْجُدْرَانِ وَالْأَسْلَاكِ وَالْحَوَاجِزِ",segs:null,full_uz:"Devorlar, simlar va to‘siqlarga qaramay.",note:"حَاجِزٌ — to‘siq."},
{num:107,time:"00:08:30,480 --> 00:08:33,399",arabic:"وَرَغْمَ التَّعَبِ الْمَحْفُورِ فِي الْوُجُوهِ",segs:[{ar:"وَرَغْمَ التَّعَبِ",uz:"va charchoqqa qaramay"},{ar:"الْمَحْفُورِ فِي الْوُجُوهِ",uz:"yuzlarga o‘yilib qolgan"}],full_uz:"Va yuzlarga o‘yilib qolgan charchoqqa qaramay.",note:"مَحْفُورٌ — o‘yilgan, chuqur iz bo‘lib qolgan."},
{num:108,time:"00:08:33,399 --> 00:08:36,759",arabic:"إِلَّا أَنَّ بَيْتَ لَحْمٍ مَا زَالَتْ تَنْبِضُ",segs:[{ar:"إِلَّا أَنَّ بَيْتَ لَحْمٍ",uz:"ammo Baytlahm"},{ar:"مَا زَالَتْ تَنْبِضُ",uz:"hamon jo‘sh urmoqda"}],full_uz:"Ammo Baytlahm hamon jo‘sh urmoqda.",note:"تَنْبِضُ — jo‘sh urmoq, urib turmoq."},
{num:109,time:"00:08:36,759 --> 00:08:38,820",arabic:"بِأَمَلٍ لَا يَنْكَسِرُ",segs:null,full_uz:"Sinmaydigan umid bilan.",note:"يَنْكَسِرُ — sinmoq."},
{num:110,time:"00:08:38,820 --> 00:08:41,200",arabic:"وَبِنُورٍ لَا يَخْبُو",segs:null,full_uz:"So‘nmaydigan nur bilan.",note:"يَخْبُو — so‘nmoq, pasaymoq."},
{num:111,time:"00:08:41,200 --> 00:08:49,060",arabic:"هِيَ لَيْسَتْ مُجَرَّدَ مَدِينَةٍ بَلْ دَعْوَةٌ صَامِتَةٌ إِلَى السَّلَامِ",segs:[{ar:"هِيَ لَيْسَتْ مُجَرَّدَ مَدِينَةٍ",uz:"u shunchaki shahar emas"},{ar:"بَلْ دَعْوَةٌ صَامِتَةٌ إِلَى السَّلَامِ",uz:"balki tinchlikka jimjit da’vat"}],full_uz:"U shunchaki shahar emas, balki tinchlikka jimjit da’vatdir.",note:"دَعْوَةٌ — da’vat, chaqiriq."},
{num:112,time:"00:08:49,060 --> 00:08:54,620",arabic:"وَرِسَالَةٌ تَقُولُ هُنَا وُلِدَتْ رِسَالَةُ الْمَحَبَّةِ",segs:[{ar:"وَرِسَالَةٌ تَقُولُ",uz:"va shunday xabar borki"},{ar:"هُنَا وُلِدَتْ رِسَالَةُ الْمَحَبَّةِ",uz:"bu yerda muhabbat xabari tug‘ilgan"}],full_uz:"Va bu yerda muhabbat xabari tug‘ilgan, deydigan bir xabardir.",note:"الْمَحَبَّةُ — muhabbat, sevgi."},
{num:113,time:"00:08:54,620 --> 00:08:57,800",arabic:"وَمَا زَالَتْ تَنْتَظِرُ مَنْ يَسْمَعُهَا",segs:[{ar:"وَمَا زَالَتْ تَنْتَظِرُ",uz:"va hamon kutmoqda"},{ar:"مَنْ يَسْمَعُهَا",uz:"uni eshitadigan kishini"}],full_uz:"Va hamon uni eshitadigan kishini kutmoqda.",note:null},
{num:114,time:"00:08:57,800 --> 00:09:03,860",arabic:"بَعِيدًا عَنْ صَخَبِ الْمُدُنِ تَنَامُ سَلْفِيتُ",segs:[{ar:"بَعِيدًا عَنْ صَخَبِ الْمُدُنِ",uz:"shaharlar shovqinidan yiroqda"},{ar:"تَنَامُ سَلْفِيتُ",uz:"Salfit sokin uyquda yotadi"}],full_uz:"Shaharlar shovqinidan yiroqda Salfit sokin uyquda yotadi.",note:"صَخَبٌ — shovqin-suron."},
{num:115,time:"00:09:03,860 --> 00:09:09,920",arabic:"مَدِينَةٌ صَغِيرَةٌ لَكِنَّهَا تَحْتَضِنُ شَيْئًا مِنْ رُوحِ فِلَسْطِينَ الْعَتِيقَةِ",segs:[{ar:"مَدِينَةٌ صَغِيرَةٌ",uz:"kichik shahar"},{ar:"لَكِنَّهَا تَحْتَضِنُ شَيْئًا",uz:"ammo u bir narsani bag‘rida saqlaydi"},{ar:"مِنْ رُوحِ فِلَسْطِينَ الْعَتِيقَةِ",uz:"qadimiy Falastin ruhidan"}],full_uz:"Kichik shahar, ammo u qadimiy Falastin ruhidan bir narsani bag‘rida saqlaydi.",note:"عَتِيقٌ — qadimiy, eski."},
{num:116,time:"00:09:09,919 --> 00:09:16,979",arabic:"فِي هَذَا الْمَكَانِ الْأَرْضُ لَا تَزَالُ تَرْوِي نَفْسَهَا",segs:[{ar:"فِي هَذَا الْمَكَانِ",uz:"bu joyda"},{ar:"الْأَرْضُ لَا تَزَالُ تَرْوِي نَفْسَهَا",uz:"yer hamon o‘z hikoyasini so‘zlaydi"}],full_uz:"Bu joyda yer hamon o‘z hikoyasini so‘zlaydi.",note:null},
{num:117,time:"00:09:16,979 --> 00:09:21,299",arabic:"تَزْهَرُ كُلَّ رَبِيعٍ وَتَزْهُو كُلَّ خَرِيفٍ",segs:[{ar:"تَزْهَرُ كُلَّ رَبِيعٍ",uz:"har bahor gullaydi"},{ar:"وَتَزْهُو كُلَّ خَرِيفٍ",uz:"har kuz yanada chiroy ochadi"}],full_uz:"Har bahor gullaydi, har kuz esa yanada chiroy ochadi.",note:"تَزْهُو — chiroy ochmoq, ko‘rkamlashmoq."},
{num:118,time:"00:09:21,299 --> 00:09:27,039",arabic:"كَأَنَّهَا لَمْ تَسْمَعْ يَوْمًا بِأَنَّ فِي الْعَالَمِ حَرْبًا أَوِ احْتِلَالًا",segs:[{ar:"كَأَنَّهَا لَمْ تَسْمَعْ يَوْمًا",uz:"go‘yo u hech qachon eshitmagandek"},{ar:"بِأَنَّ فِي الْعَالَمِ حَرْبًا أَوِ احْتِلَالًا",uz:"dunyoda urush yoki bosqin borligini"}],full_uz:"Go‘yo u dunyoda urush yoki bosqin borligini hech qachon eshitmagandek.",note:"احْتِلَالٌ — bosib olish, ishg‘ol."},
{num:119,time:"00:09:27,039 --> 00:09:36,599",arabic:"بُيُوتٌ بَسِيطَةٌ بِقُلُوبٍ كَبِيرَةٍ",segs:[{ar:"بُيُوتٌ بَسِيطَةٌ",uz:"sodda uylar"},{ar:"بِقُلُوبٍ كَبِيرَةٍ",uz:"katta qalblar bilan"}],full_uz:"Katta qalblarga ega sodda uylar.",note:null},
{num:120,time:"00:09:36,599 --> 00:09:39,319",arabic:"مَبْنِيَّةٌ بِالْحَجَرِ وَالتُّرَابِ",segs:null,full_uz:"Tosh va tuproqdan qurilgan.",note:"مَبْنِيٌّ — qurilgan."},
{num:121,time:"00:09:39,320 --> 00:09:42,120",arabic:"لَكِنْ أَسَاسُهَا الطُّمَأْنِينَةُ",segs:null,full_uz:"Ammo uning asosi xotirjamlik.",note:"الطُّمَأْنِينَةُ — xotirjamlik, ko‘ngil osoyishtaligi."},
{num:122,time:"00:09:42,120 --> 00:09:45,060",arabic:"جُدْرَانُهَا تَهْمِسُ بِالْحِكَايَاتِ",segs:null,full_uz:"Uning devorlari hikoyalarni shivirlaydi.",note:null},
{num:123,time:"00:09:45,060 --> 00:09:49,340",arabic:"وَأَبْوَابُهَا لَا تُغْلَقُ أَبَدًا فِي وَجْهِ الْعَابِرِينَ",segs:[{ar:"وَأَبْوَابُهَا لَا تُغْلَقُ أَبَدًا",uz:"uning eshiklari hech qachon yopilmaydi"},{ar:"فِي وَجْهِ الْعَابِرِينَ",uz:"o‘tkinchilar qarshisida"}],full_uz:"Uning eshiklari o‘tkinchilar qarshisida hech qachon yopilmaydi.",note:"الْعَابِرُونَ — o‘tkinchilar, yo‘lovchilar."},
{num:124,time:"00:09:49,340 --> 00:09:55,440",arabic:"فِي سَلْفِيتَ وَالرِّيفِ الْفِلَسْطِينِيِّ",segs:null,full_uz:"Salfit va Falastin qishloqlarida.",note:"الرِّيفُ — qishloq hududi, qishloq joylar."},
{num:125,time:"00:09:55,440 --> 00:09:57,760",arabic:"الْوَقْتُ يَمْشِي عَلَى مَهْلٍ",segs:null,full_uz:"Vaqt sekin yuradi.",note:"عَلَى مَهْلٍ — shoshmasdan, sekin."},
{num:126,time:"00:09:57,760 --> 00:10:01,200",arabic:"كَأَنَّ الْعَالَمَ قَرَّرَ أَنْ يَسْتَرِيحَ هُنَا",segs:[{ar:"كَأَنَّ الْعَالَمَ قَرَّرَ",uz:"go‘yo dunyo qaror qilgandek"},{ar:"أَنْ يَسْتَرِيحَ هُنَا",uz:"shu yerda dam olishga"}],full_uz:"Go‘yo dunyo shu yerda dam olishga qaror qilgandek.",note:"اسْتَرَاحَ — dam olmoq."},
{num:127,time:"00:10:01,200 --> 00:10:09,680",arabic:"الزَّيْتُونُ لَيْسَ فَقَطْ شَجَرَةً",segs:[{ar:"الزَّيْتُونُ لَيْسَ فَقَطْ",uz:"zaytun shunchaki"},{ar:"شَجَرَةً",uz:"daraxt emas"}],full_uz:"Zaytun shunchaki daraxt emas.",note:null},
{num:128,time:"00:10:09,680 --> 00:10:12,259",arabic:"هُوَ شَاهِدٌ عَلَى كُلِّ الْفُصُولِ",segs:[{ar:"هُوَ شَاهِدٌ",uz:"u guvohdir"},{ar:"عَلَى كُلِّ الْفُصُولِ",uz:"barcha fasllarga"}],full_uz:"U barcha fasllarga guvoh.",note:null},
{num:129,time:"00:10:12,259 --> 00:10:16,200",arabic:"وَرَمْزٌ لِصَبْرِ شَعْبٍ لَمْ يَنْكَسِرْ",segs:[{ar:"وَرَمْزٌ لِصَبْرِ شَعْبٍ",uz:"va bir xalq sabrining ramzi"},{ar:"لَمْ يَنْكَسِرْ",uz:"sinmagan"}],full_uz:"Va sinmagan bir xalqning sabriga ramz.",note:null},
{num:130,time:"00:10:20,200 --> 00:10:22,860",arabic:"أَصْوَاتُ الضَّحِكَاتِ الرِّيفِيَّةِ",segs:null,full_uz:"Qishloq kulgilarining ovozlari.",note:null},
{num:131,time:"00:10:22,860 --> 00:10:26,600",arabic:"صَوْتُ الدَّجَاجِ فِي الْفَجْرِ",segs:null,full_uz:"Tongdagi xo‘roz ovozi.",note:null},
{num:132,time:"00:10:26,600 --> 00:10:30,240",arabic:"الْمَاعِزُ وَهِيَ تَمُرُّ فِي الْمَمَرَّاتِ الْحَجَرِيَّةِ",segs:[{ar:"الْمَاعِزُ",uz:"echkilar"},{ar:"وَهِيَ تَمُرُّ فِي الْمَمَرَّاتِ الْحَجَرِيَّةِ",uz:"tosh yo‘laklardan o‘tib borayotgan"}],full_uz:"Tosh yo‘laklardan o‘tib borayotgan echkilar.",note:null},
{num:133,time:"00:10:30,240 --> 00:10:36,639",arabic:"كُلُّهَا مَقَاطِعُ مُوسِيقِيَّةٌ لَا تُسَجَّلُ لَكِنَّهَا تُحَسُّ",segs:[{ar:"كُلُّهَا مَقَاطِعُ مُوسِيقِيَّةٌ",uz:"bularning barchasi musiqiy parchalar"},{ar:"لَا تُسَجَّلُ لَكِنَّهَا تُحَسُّ",uz:"yozib olinmaydi, ammo his qilinadi"}],full_uz:"Bularning barchasi yozib olinmaydigan, ammo his qilinadigan musiqiy parchalardir.",note:"مَقْطَعٌ — parcha, bo‘lak."},
{num:134,time:"00:10:36,639 --> 00:10:44,639",arabic:"هُنَا حَيْثُ الْأَرْضُ أُمٌّ وَحَيْثُ الْبَسَاطَةُ جَمَالٌ",segs:[{ar:"هُنَا حَيْثُ الْأَرْضُ أُمٌّ",uz:"bu yerda yer onadir"},{ar:"وَحَيْثُ الْبَسَاطَةُ جَمَالٌ",uz:"va soddalik go‘zallikdir"}],full_uz:"Bu yerda yer ona, soddalik esa go‘zallikdir.",note:null},
{num:135,time:"00:10:44,639 --> 00:10:48,340",arabic:"تُولَدُ فِلَسْطِينُ مِنْ جَدِيدٍ كُلَّ صَبَاحٍ",segs:[{ar:"تُولَدُ فِلَسْطِينُ مِنْ جَدِيدٍ",uz:"Falastin yangidan tug‘iladi"},{ar:"كُلَّ صَبَاحٍ",uz:"har tong"}],full_uz:"Falastin har tong yangidan tug‘iladi.",note:null},
{num:136,time:"00:10:48,340 --> 00:10:55,539",arabic:"مَعَ أَوَّلِ خَيْطِ شَمْسٍ مِنْ بَيْنِ زَيْتُونَةٍ صَامِدَةٍ وَأُغْنِيَةٍ لَا تَنْتَهِي",segs:[{ar:"مَعَ أَوَّلِ خَيْطِ شَمْسٍ",uz:"quyoshning ilk nuri bilan"},{ar:"مِنْ بَيْنِ زَيْتُونَةٍ صَامِدَةٍ",uz:"bardoshli zaytun daraxti orasidan"},{ar:"وَأُغْنِيَةٍ لَا تَنْتَهِي",uz:"va tugamaydigan qo‘shiq bilan"}],full_uz:"Quyoshning bardoshli zaytun daraxti orasidan tushgan ilk nuri va tugamaydigan qo‘shiq bilan.",note:"صَامِدٌ — bardoshli, sobit."},
{num:137,time:"00:11:00,240 --> 00:11:02,560",arabic:"فِي قَلْبِ صَحْرَاءِ يَهُودَا",segs:null,full_uz:"Yahudiya sahrosining qalbida.",note:null},
{num:138,time:"00:11:02,560 --> 00:11:06,100",arabic:"وَبَيْنَ جُرُوفٍ حَجَرِيَّةٍ تُعَانِقُ الْفَرَاغَ",segs:[{ar:"وَبَيْنَ جُرُوفٍ حَجَرِيَّةٍ",uz:"qoyali jarliklar orasida"},{ar:"تُعَانِقُ الْفَرَاغَ",uz:"bo‘shliqni quchoqlaydigan"}],full_uz:"Bo‘shliqni quchoqlagan qoyali jarliklar orasida.",note:null},
{num:139,time:"00:11:06,100 --> 00:11:11,360",arabic:"يَظْهَرُ دَيْرُ مَارْسَابَا كَأَنَّهُ وَحْيٌ مَنْحُوتٌ فِي الصَّخْرِ",segs:[{ar:"يَظْهَرُ دَيْرُ مَارْسَابَا",uz:"Mar Saba monastiri ko‘rinadi"},{ar:"كَأَنَّهُ وَحْيٌ مَنْحُوتٌ فِي الصَّخْرِ",uz:"go‘yo qoyaga o‘yilgan vahiydek"}],full_uz:"Mar Saba monastiri go‘yo qoyaga o‘yilgan vahiydek ko‘rinadi.",note:"وَحْيٌ — vahiy, ilhom. مَنْحُوتٌ — o‘yilgan."},
{num:140,time:"00:11:11,360 --> 00:11:16,620",arabic:"صَامِدٌ هَادِئٌ وَكَأَنَّهُ خَارِجَ الزَّمَنِ",segs:[{ar:"صَامِدٌ هَادِئٌ",uz:"sokin va sobit"},{ar:"وَكَأَنَّهُ خَارِجَ الزَّمَنِ",uz:"go‘yo zamondan tashqarida"}],full_uz:"Sokin va sobit, go‘yo zamondan tashqarida.",note:"صَامِدٌ — sobit, bardoshli."},
{num:141,time:"00:11:16,620 --> 00:11:24,019",arabic:"مِنْ بَعِيدٍ يَبْدُو كَمَشْهَدٍ مِنْ حُلْمٍ بَيْزَنْطِيٍّ",segs:[{ar:"مِنْ بَعِيدٍ يَبْدُو",uz:"uzoqdan ko‘rinadi"},{ar:"كَمَشْهَدٍ مِنْ حُلْمٍ بَيْزَنْطِيٍّ",uz:"Vizantiya tushidagi manzaradek"}],full_uz:"Uzoqdan Vizantiya tushidagi manzaradek ko‘rinadi.",note:"بَيْزَنْطِيٌّ — vizantiya uslubidagi, Vizantiyaga oid."},
{num:142,time:"00:11:24,019 --> 00:11:26,899",arabic:"أَبْرَاجٌ وَقِبَابٌ مُذَهَّبَةٌ",segs:null,full_uz:"Oltin suvi yuritilgan minoralar va gumbazlar.",note:"مُذَهَّبٌ — zarhal qilingan."},
{num:143,time:"00:11:26,899 --> 00:11:28,940",arabic:"وَجُدْرَانٌ كَالْعَسَلِ",segs:null,full_uz:"Asaldek devorlar.",note:null},
{num:144,time:"00:11:28,940 --> 00:11:32,360",arabic:"مُتَدَرِّجَةٌ فَوْقَ مُنْحَدَرٍ صَخْرِيٍّ",segs:null,full_uz:"Qoyali yonbag‘ir bo‘ylab pog‘onama-pog‘ona joylashgan.",note:"مُتَدَرِّجٌ — pog‘onama-pog‘ona joylashgan."},
{num:145,time:"00:11:32,360 --> 00:11:36,820",arabic:"تُطِلُّ عَلَى وَادٍ سَحِيقٍ يُدْعَى وَادِي قِدْرُونَ",segs:[{ar:"تُطِلُّ عَلَى وَادٍ سَحِيقٍ",uz:"chuqur vodiyga qaragan"},{ar:"يُدْعَى وَادِي قِدْرُونَ",uz:"Qidron vodiysi deb ataladigan"}],full_uz:"Qidron vodiysi deb ataladigan chuqur vodiyga qaragan.",note:"سَحِيقٌ — juda chuqur, tubsizdek."},
{num:146,time:"00:11:36,820 --> 00:11:45,820",arabic:"أَسَّسَهُ الرَّاهِبُ الْقِدِّيسُ سَابَا فِي الْقَرْنِ الْخَامِسِ",segs:[{ar:"أَسَّسَهُ الرَّاهِبُ الْقِدِّيسُ سَابَا",uz:"uni avliyo rohib Saba asos solgan"},{ar:"فِي الْقَرْنِ الْخَامِسِ",uz:"beshinchi asrda"}],full_uz:"Uni beshinchi asrda avliyo rohib Saba asos solgan.",note:"أَسَّسَ — asos solmoq."},
{num:147,time:"00:11:45,820 --> 00:11:49,520",arabic:"وَمُنْذُ ذَلِكَ الْحِينِ لَمْ يَخْفُتْ نُورُهُ",segs:[{ar:"وَمُنْذُ ذَلِكَ الْحِينِ",uz:"o‘sha paytdan beri"},{ar:"لَمْ يَخْفُتْ نُورُهُ",uz:"uning nuri so‘nmagan"}],full_uz:"O‘sha paytdan beri uning nuri so‘nmagan.",note:"يَخْفُتُ — so‘nmoq, xiralashmoq."},
{num:148,time:"00:11:49,520 --> 00:11:54,200",arabic:"فَهُوَ أَحَدُ أَقْدَمِ الْأَدْيِرَةِ الْمَسِيحِيَّةِ الْمَأْهُولَةِ بِالْعَالَمِ",segs:[{ar:"فَهُوَ أَحَدُ أَقْدَمِ الْأَدْيِرَةِ الْمَسِيحِيَّةِ",uz:"u eng qadimiy xristian monastirlaridan biridir"},{ar:"الْمَأْهُولَةِ بِالْعَالَمِ",uz:"dunyodagi aholi yashaydigan"}],full_uz:"U dunyodagi doimiy yashab kelinayotgan eng qadimiy xristian monastirlaridan biridir.",note:"مَأْهُولٌ — aholi yashaydigan."},
{num:149,time:"00:11:54,200 --> 00:11:56,980",arabic:"مُقَدَّسٌ لِلرُّومِ الْأَرْثُوذُوكْسِ",segs:null,full_uz:"Pravoslav rimliklar uchun muqaddas.",note:"مُقَدَّسٌ — muqaddas."},
{num:150,time:"00:11:56,980 --> 00:11:59,740",arabic:"وَمَهَابٌ بِصَمْتِهِ الْعَمِيقِ",segs:null,full_uz:"Chuqur sukunati bilan haybatli.",note:"مَهَابٌ — haybatli, salobatli."},
{num:151,time:"00:11:59,740 --> 00:12:07,259",arabic:"هُنَا لَا تَسْمَعُ الضَّوْضَاءَ",segs:null,full_uz:"Bu yerda shovqinni eshitmaysiz.",note:"الضَّوْضَاءُ — shovqin-suron."},
{num:152,time:"00:12:07,259 --> 00:12:11,100",arabic:"فَالدَّيْرُ لَا يُفْتَحُ لِلنِّسَاءِ مُنْذُ قُرُونٍ",segs:[{ar:"فَالدَّيْرُ لَا يُفْتَحُ لِلنِّسَاءِ",uz:"monastir ayollar uchun ochilmaydi"},{ar:"مُنْذُ قُرُونٍ",uz:"asrlardan beri"}],full_uz:"Monastir asrlardan beri ayollar uchun ochilmaydi.",note:"يُفْتَحُ لِـ — ... uchun ochilmoq."},
{num:153,time:"00:12:11,100 --> 00:12:14,200",arabic:"وَتَسْكُنُهُ رُوحُ الْعُزْلَةِ وَالنُّسْكِ",segs:[{ar:"وَتَسْكُنُهُ رُوحُ الْعُزْلَةِ",uz:"unda yolg‘izlik ruhi yashaydi"},{ar:"وَالنُّسْكِ",uz:"va tarkidunyochilik"}],full_uz:"Unda yolg‘izlik va tarkidunyochilik ruhi yashaydi.",note:"النُّسْكُ — ibodatga berilish, tarkidunyochilik."},
{num:154,time:"00:12:14,200 --> 00:12:18,100",arabic:"رُهْبَانٌ يَعِيشُونَ حَيَاةً بَسِيطَةً",segs:[{ar:"رُهْبَانٌ",uz:"rohiblar"},{ar:"يَعِيشُونَ حَيَاةً بَسِيطَةً",uz:"sodda hayot kechiradilar"}],full_uz:"Rohiblar sodda hayot kechiradilar.",note:"رَهْبَانٌ — rohiblar."},
{num:155,time:"00:12:18,100 --> 00:12:19,860",arabic:"مُنْقَطِعَةٌ عَنِ الْعَالَمِ",segs:null,full_uz:"Dunyodan uzilgan.",note:"مُنْقَطِعٌ عَنِ — ...dan uzilgan."},
{num:156,time:"00:12:19,860 --> 00:12:21,960",arabic:"يَتَعَبَّدُونَ فِي صَمْتٍ",segs:null,full_uz:"Ular sukutda ibodat qiladilar.",note:"يَتَعَبَّدُ — ibodat qilmoq."},
{num:157,time:"00:12:21,960 --> 00:12:26,120",arabic:"وَيَكْتُبُونَ بِقُلُوبِهِمْ فُصُولَ التَّأَمُّلِ وَالتَّسْلِيمِ",segs:[{ar:"وَيَكْتُبُونَ بِقُلُوبِهِمْ",uz:"qalblari bilan yozadilar"},{ar:"فُصُولَ التَّأَمُّلِ وَالتَّسْلِيمِ",uz:"tafakkur va taslim bo‘lish boblarini"}],full_uz:"Qalblari bilan tafakkur va taslim bo‘lish boblarini yozadilar.",note:"التَّسْلِيمُ — taslim bo‘lish, bo‘ysunish."},
{num:158,time:"00:12:26,120 --> 00:12:32,560",arabic:"وَعِنْدَمَا تُطِلُّ مِنْ شُرْفَةِ الدَّيْرِ",segs:[{ar:"وَعِنْدَمَا تُطِلُّ",uz:"qaraganingizda"},{ar:"مِنْ شُرْفَةِ الدَّيْرِ",uz:"monastir ayvonidan"}],full_uz:"Monastir ayvonidan qaraganingizda.",note:"أَطَلَّ مِنْ — ...dan qaramoq, nazar tashlamoq."},
{num:159,time:"00:12:32,560 --> 00:12:36,519",arabic:"تَشْعُرُ وَكَأَنَّكَ تَنْظُرُ إِلَى الزَّمَنِ نَفْسِهِ",segs:[{ar:"تَشْعُرُ وَكَأَنَّكَ",uz:"go‘yo ...dek his qilasiz"},{ar:"تَنْظُرُ إِلَى الزَّمَنِ نَفْسِهِ",uz:"zamonning o‘ziga qarayotganingizni"}],full_uz:"Go‘yo zamonning o‘ziga qarayotgandek his qilasiz.",note:null},
{num:160,time:"00:12:36,519 --> 00:12:41,120",arabic:"كُلُّ حَجَرٍ، كُلُّ زَاوِيَةٍ تَحْمِلُ صَلَاةً قَدِيمَةً",segs:[{ar:"كُلُّ حَجَرٍ، كُلُّ زَاوِيَةٍ",uz:"har bir tosh, har bir burchak"},{ar:"تَحْمِلُ صَلَاةً قَدِيمَةً",uz:"qadimiy bir ibodatni olib yuradi"}],full_uz:"Har bir tosh, har bir burchak qadimiy bir ibodatni o‘zida saqlaydi.",note:null},
{num:161,time:"00:12:41,120 --> 00:12:44,019",arabic:"وَهَمْسًا مِنْ قُرُونٍ بَعِيدَةٍ",segs:null,full_uz:"Va uzoq asrlardan qolgan shivirni.",note:"هَمْسٌ — shivir."},
{num:162,time:"00:12:44,019 --> 00:12:48,259",arabic:"حِينَ كَانَ الْإِيمَانُ أَقْرَبَ إِلَى الصَّمْتِ مِنْهُ إِلَى الْقَوْلِ",segs:[{ar:"حِينَ كَانَ الْإِيمَانُ",uz:"iymon bo‘lgan paytda"},{ar:"أَقْرَبَ إِلَى الصَّمْتِ",uz:"sukunatga yaqinroq"},{ar:"مِنْهُ إِلَى الْقَوْلِ",uz:"so‘zga qaraganda"}],full_uz:"Iymon so‘zdan ko‘ra sukunatga yaqinroq bo‘lgan paytlarda.",note:"الْقَوْلُ — so‘z, nutq."},
{num:163,time:"00:12:48,259 --> 00:12:55,720",arabic:"مَارْسَابَا لَيْسَ مُجَرَّدَ دَيْرٍ",segs:[{ar:"مَارْسَابَا",uz:"Mar Saba"},{ar:"لَيْسَ مُجَرَّدَ دَيْرٍ",uz:"shunchaki monastir emas"}],full_uz:"Mar Saba shunchaki monastir emas.",note:null},
{num:164,time:"00:12:55,720 --> 00:12:59,040",arabic:"بَلْ نَشِيدٌ رُوحِيٌّ مُعَلَّقٌ عَلَى هَاوِيَةٍ",segs:[{ar:"بَلْ نَشِيدٌ رُوحِيٌّ",uz:"balki ruhiy madhiyadir"},{ar:"مُعَلَّقٌ عَلَى هَاوِيَةٍ",uz:"jar ustida osilib turgan"}],full_uz:"Balki jar ustida osilib turgan ruhiy madhiyadir.",note:"نَشِيدٌ — nashida, madhiyа. هَاوِيَةٌ — chuqur jarlik."},
{num:165,time:"00:12:59,040 --> 00:13:04,720",arabic:"يُذَكِّرُكَ أَنَّ هُنَاكَ أَمَاكِنَ لَا يُقَاسُ جَمَالُهَا بِالْحَوَاسِّ",segs:[{ar:"يُذَكِّرُكَ أَنَّ هُنَاكَ أَمَاكِنَ",uz:"sizga shunday joylar borligini eslatadi"},{ar:"لَا يُقَاسُ جَمَالُهَا بِالْحَوَاسِّ",uz:"ularning go‘zalligi sezgi a’zolari bilan o‘lchanmaydigan"}],full_uz:"Sizga go‘zalligi sezgi a’zolari bilan o‘lchanmaydigan joylar borligini eslatadi.",note:"الْحَوَاسُّ — sezgi a’zolari."},
{num:166,time:"00:13:04,720 --> 00:13:09,320",arabic:"بَلْ بِمَا تُثِيرُهُ فِي الْقَلْبِ مِنْ سَكِينَةٍ وَخُشُوعٍ",segs:[{ar:"بَلْ بِمَا تُثِيرُهُ فِي الْقَلْبِ",uz:"balki qalbda uyg‘otadigan narsa bilan"},{ar:"مِنْ سَكِينَةٍ وَخُشُوعٍ",uz:"sokinlik va xushu’dan"}],full_uz:"Balki qalbda uyg‘otadigan sokinlik va xushu’ bilan.",note:"تُثِيرُ — uyg‘otmoq, qo‘zg‘atmoq."},
{num:167,time:"00:13:09,320 --> 00:13:19,720",arabic:"فِي الْخَلِيلِ تَنْبِضُ الْأَرْضُ بِتَارِيخٍ لَا يُشْبِهُ سِوَاهُ",segs:[{ar:"فِي الْخَلِيلِ",uz:"Xalilda"},{ar:"تَنْبِضُ الْأَرْضُ بِتَارِيخٍ",uz:"yer tarix bilan jo‘sh uradi"},{ar:"لَا يُشْبِهُ سِوَاهُ",uz:"unga o‘xshashi yo‘q"}],full_uz:"Xalilda yer o‘xshashi yo‘q tarix bilan jo‘sh uradi.",note:"لَا يُشْبِهُ سِوَاهُ — unga o‘xshashi yo‘q."},
{num:168,time:"00:13:20,300 --> 00:13:24,360",arabic:"مَدِينَةٌ تُمْسِكُ بِجُذُورِهَا فِي أَعْمَاقِ الزَّمَنِ",segs:[{ar:"مَدِينَةٌ تُمْسِكُ بِجُذُورِهَا",uz:"ildizlarini mahkam ushlagan shahar"},{ar:"فِي أَعْمَاقِ الزَّمَنِ",uz:"zamon qa’rida"}],full_uz:"Ildizlarini zamon qa’rida mahkam ushlagan shahar.",note:"جُذُورٌ — ildizlar."},
{num:169,time:"00:13:24,360 --> 00:13:28,000",arabic:"وَتُعَانِقُ حَاضِرَهَا بِإِصْرَارٍ لَا يَلِينُ",segs:[{ar:"وَتُعَانِقُ حَاضِرَهَا",uz:"va o‘z bugunini quchoqlaydi"},{ar:"بِإِصْرَارٍ لَا يَلِينُ",uz:"bukilmaydigan qat’iyat bilan"}],full_uz:"Va o‘z bugunini bukilmaydigan qat’iyat bilan quchoqlaydi.",note:"يَلِينُ — yumshamoq, bo‘shashmoq."},
{num:170,time:"00:13:28,000 --> 00:13:36,399",arabic:"هُنَا يَرْقُدُ إِبْرَاهِيمُ الْخَلِيلُ أَبُو الْأَنْبِيَاءِ",segs:[{ar:"هُنَا يَرْقُدُ إِبْرَاهِيمُ الْخَلِيلُ",uz:"bu yerda Ibrohim Xalil yotadi"},{ar:"أَبُو الْأَنْبِيَاءِ",uz:"payg‘ambarlarning otasi"}],full_uz:"Bu yerda payg‘ambarlarning otasi Ibrohim Xalil yotadi.",note:"يَرْقُدُ — yotmoq, orom olmoq."},
{num:171,time:"00:13:36,399 --> 00:13:39,519",arabic:"فِي حِضْنِ الْحَرَمِ الْإِبْرَاهِيمِيِّ الشَّرِيفِ",segs:[{ar:"فِي حِضْنِ الْحَرَمِ الْإِبْرَاهِيمِيِّ",uz:"Ibrohimiy Haram bag‘rida"},{ar:"الشَّرِيفِ",uz:"sharif, muqaddas"}],full_uz:"Muqaddas Ibrohimiy Haram bag‘rida.",note:"حِضْنٌ — bag‘ir, quchoq."},
{num:172,time:"00:13:39,519 --> 00:13:42,100",arabic:"ذَلِكَ الْمَقَامُ الْمَهِيبُ",segs:null,full_uz:"O‘sha haybatli maqom.",note:"مَقَامٌ — maqom, muqaddas joy."},
{num:173,time:"00:13:42,100 --> 00:13:46,120",arabic:"حَيْثُ تَتَشَابَكُ الْأَدْيَانُ وَتَتَشَظَّى الرِّوَايَاتُ",segs:[{ar:"حَيْثُ تَتَشَابَكُ الْأَدْيَانُ",uz:"u yerda dinlar bir-biriga qorishadi"},{ar:"وَتَتَشَظَّى الرِّوَايَاتُ",uz:"rivoyatlar esa parchalangan"}],full_uz:"U yerda dinlar bir-biriga qorishadi, rivoyatlar esa parchalanadi.",note:"تَتَشَظَّى — parchalanmoq, bo‘linib ketmoq."},
{num:174,time:"00:13:46,120 --> 00:13:48,300",arabic:"لَكِنَّ الْحَقِيقَةَ وَاحِدَةٌ",segs:null,full_uz:"Ammo haqiqat bitta.",note:null},
{num:175,time:"00:13:48,300 --> 00:13:51,980",arabic:"هَذَا الْمَكَانُ مُقَدَّسٌ مُنْذُ فَجْرِ الْإِنْسَانِ",segs:[{ar:"هَذَا الْمَكَانُ مُقَدَّسٌ",uz:"bu joy muqaddas"},{ar:"مُنْذُ فَجْرِ الْإِنْسَانِ",uz:"insoniyat tongidan beri"}],full_uz:"Bu joy insoniyat tongidan beri muqaddas.",note:null},
{num:176,time:"00:13:51,980 --> 00:14:01,159",arabic:"فِي شَوَارِعِ الْبَلْدَةِ الْقَدِيمَةِ يَخْتَلِطُ صَوْتُ الْبَاعَةِ بِنِدَاءِ الْأَذَانِ",segs:[{ar:"فِي شَوَارِعِ الْبَلْدَةِ الْقَدِيمَةِ",uz:"Eski shahar ko‘chalarida"},{ar:"يَخْتَلِطُ صَوْتُ الْبَاعَةِ",uz:"sotuvchilarning ovozi qorishadi"},{ar:"بِنِدَاءِ الْأَذَانِ",uz:"azon nidosiga"}],full_uz:"Eski shahar ko‘chalarida sotuvchilarning ovozi azon nidosiga qorishadi.",note:null},
{num:177,time:"00:14:01,159 --> 00:14:11,420",arabic:"وَحِجَارَةُ الْجُدْرَانِ تَتَحَدَّثُ بِلَهْجَةٍ قَدِيمَةٍ عَنْ قُرُونٍ مِنَ الْحِصَارِ وَالْمُقَاوَمَةِ وَالصَّبْرِ",segs:[{ar:"وَحِجَارَةُ الْجُدْرَانِ تَتَحَدَّثُ بِلَهْجَةٍ قَدِيمَةٍ",uz:"devor toshlari qadimiy ohangda so‘zlaydi"},{ar:"عَنْ قُرُونٍ مِنَ الْحِصَارِ وَالْمُقَاوَمَةِ وَالصَّبْرِ",uz:"asrlar davom etgan qamal, qarshilik va sabr haqida"}],full_uz:"Devor toshlari asrlar davom etgan qamal, qarshilik va sabr haqida qadimiy ohangda so‘zlaydi.",note:"لَهْجَةٌ — lahja, ohang. حِصَارٌ — qamal."},
{num:178,time:"00:14:11,420 --> 00:14:18,519",arabic:"الْخَلِيلُ لَيْسَتْ مَدِينَةً عَادِيَّةً إِنَّهَا حِصْنٌ لِلْكَرَامَةِ",segs:[{ar:"الْخَلِيلُ لَيْسَتْ مَدِينَةً عَادِيَّةً",uz:"Xalil oddiy shahar emas"},{ar:"إِنَّهَا حِصْنٌ لِلْكَرَامَةِ",uz:"u qadr-qimmat qal’asi"}],full_uz:"Xalil oddiy shahar emas, u qadr-qimmat qal’asidir.",note:"حِصْنٌ — qal’a, mustahkam maskan."},
{num:179,time:"00:14:18,519 --> 00:14:21,899",arabic:"وَحِكَايَةُ شَعْبٍ يَزْرَعُ الْحَيَاةَ رَغْمَ الْحَوَاجِزِ",segs:[{ar:"وَحِكَايَةُ شَعْبٍ",uz:"va bir xalqning hikoyasi"},{ar:"يَزْرَعُ الْحَيَاةَ رَغْمَ الْحَوَاجِزِ",uz:"to‘siqlarga qaramay hayotni barpo etadigan"}],full_uz:"Va to‘siqlarga qaramay hayotni barpo etayotgan xalqning hikoyasi.",note:"رَغْمَ — ...ga qaramay."},
{num:180,time:"00:14:21,899 --> 00:14:24,699",arabic:"وَيُرَمِّمُ الْبُيُوتَ رَغْمَ الشُّقُوقِ",segs:[{ar:"وَيُرَمِّمُ الْبُيُوتَ",uz:"va uylarni ta’mirlaydi"},{ar:"رَغْمَ الشُّقُوقِ",uz:"yoriqlarga qaramay"}],full_uz:"Va yoriqlarga qaramay uylarni ta’mirlaydi.",note:"رَمَّمَ — ta’mirlamoq. شَقٌّ — yoriq."},
{num:181,time:"00:14:24,699 --> 00:14:31,639",arabic:"تَتَجَوَّلُ فِي أَسْوَاقِهَا الْمَسْقُوفَةِ",segs:[{ar:"تَتَجَوَّلُ",uz:"kezib yurasiz"},{ar:"فِي أَسْوَاقِهَا الْمَسْقُوفَةِ",uz:"uning tomi yopiq bozorlarida"}],full_uz:"Uning tomi yopiq bozorlarida kezib yurasiz.",note:"مَسْقُوفٌ — tomi yopiq."},
{num:182,time:"00:14:31,639 --> 00:14:35,519",arabic:"تَلْمَحُ وُجُوهًا تَعْبَقُ بِالْأَصَالَةِ",segs:[{ar:"تَلْمَحُ وُجُوهًا",uz:"yuzlarni ko‘rasiz"},{ar:"تَعْبَقُ بِالْأَصَالَةِ",uz:"asl ruh bilan yashnagan"}],full_uz:"Asl ruhni aks ettiradigan yuzlarni ko‘rasiz.",note:"الْأَصَالَةُ — asl­lik, o‘ziga xos an’ana."},
{num:183,time:"00:14:35,519 --> 00:14:40,000",arabic:"وَأَيَادِي تَنْسُجُ الصُّوفَ وَتَخْبِزُ الزَّادَ",segs:[{ar:"وَأَيَادِي تَنْسُجُ الصُّوفَ",uz:"va jun to‘qiyotgan qo‘llar"},{ar:"وَتَخْبِزُ الزَّادَ",uz:"yo‘l oziqasini pishirayotgan"}],full_uz:"Jun to‘qiyotgan va yo‘l oziqasini pishirayotgan qo‘llarni ko‘rasiz.",note:"الزَّادُ — yo‘l uchun oziqa, safar taomi."},
{num:184,time:"00:14:40,000 --> 00:14:43,720",arabic:"وَتَصْنَعُ مِنَ الْبَسَاطَةِ إِرْثًا خَالِدًا",segs:[{ar:"وَتَصْنَعُ مِنَ الْبَسَاطَةِ",uz:"soddalikdan yaratadi"},{ar:"إِرْثًا خَالِدًا",uz:"abadiy meros"}],full_uz:"Soddalikdan abadiy meros yaratadi.",note:"إِرْثٌ — meros."},
{num:185,time:"00:14:43,720 --> 00:14:50,660",arabic:"وَحِينَ تَغِيبُ الشَّمْسُ خَلْفَ تِلَالِ الْخَلِيلِ",segs:[{ar:"وَحِينَ تَغِيبُ الشَّمْسُ",uz:"quyosh botganda"},{ar:"خَلْفَ تِلَالِ الْخَلِيلِ",uz:"Xalil tepaliklari ortida"}],full_uz:"Quyosh Xalil tepaliklari ortida botganda.",note:null},
{num:186,time:"00:14:50,660 --> 00:14:53,840",arabic:"تُضَاءُ الْمَدِينَةُ بِشُمُوعِ الْإِيمَانِ",segs:[{ar:"تُضَاءُ الْمَدِينَةُ",uz:"shahar yoritiladi"},{ar:"بِشُمُوعِ الْإِيمَانِ",uz:"iymon shamchalari bilan"}],full_uz:"Shahar iymon shamchalari bilan yoritiladi.",note:"شُمُوعٌ — shamlar."},
{num:187,time:"00:14:53,840 --> 00:15:00,000",arabic:"وَتَهْمِسُ الرِّيحُ بِأَسْمَاءٍ سَكَنَتْ هَذِهِ الْأَرْضَ مُنْذُ آلَافِ السِّنِينَ",segs:[{ar:"وَتَهْمِسُ الرِّيحُ بِأَسْمَاءٍ",uz:"shamol ismlarni shivirlaydi"},{ar:"سَكَنَتْ هَذِهِ الْأَرْضَ مُنْذُ آلَافِ السِّنِينَ",uz:"minglab yillardan beri bu yurtda yashagan"}],full_uz:"Shamol minglab yillardan beri bu yurtda yashagan ismlarni shivirlaydi.",note:null},
{num:188,time:"00:15:00,000 --> 00:15:01,660",arabic:"وَلَا تَزَالُ",segs:null,full_uz:"Va hamon.",note:"مَا زَالَ / لَا يَزَالُ — hamon, hanuz."},
{num:189,time:"00:15:01,660 --> 00:15:10,300",arabic:"فِي سَبَسْطِيَةَ حَيْثُ تَتَعَانَقُ الْحَضَارَاتُ وَتَتَمَوَّجُ الْقُرُونُ",segs:[{ar:"فِي سَبَسْطِيَةَ",uz:"Sabastiyada"},{ar:"حَيْثُ تَتَعَانَقُ الْحَضَارَاتُ",uz:"sivilizatsiyalar quchoqlashadigan joyda"},{ar:"وَتَتَمَوَّجُ الْقُرُونُ",uz:"asrlar to‘lqinlanadigan joyda"}],full_uz:"Sabastiyada, sivilizatsiyalar quchoqlashib, asrlar to‘lqinlanadigan joyda.",note:"تَتَمَوَّجُ — to‘lqinlanmoq."},
{num:190,time:"00:15:10,299 --> 00:15:13,919",arabic:"تَرْقُدُ أَطْلَالٌ رُومَانِيَّةٌ شَامِخَةٌ",segs:[{ar:"تَرْقُدُ أَطْلَالٌ رُومَانِيَّةٌ",uz:"qadimiy Rim xarobalari yotadi"},{ar:"شَامِخَةٌ",uz:"salobatli, qad rostlagan"}],full_uz:"Salobatli qadimiy Rim xarobalari yotadi.",note:"أَطْلَالٌ — xarobalar."},
{num:191,time:"00:15:13,919 --> 00:15:16,539",arabic:"لَا تَزَالُ تَرْوِي قِصَّةَ الزَّمَنِ",segs:null,full_uz:"Ular hamon zamon hikoyasini so‘zlaydi.",note:"لَا تَزَالُ — hamon davom etmoqda."},
{num:192,time:"00:15:16,539 --> 00:15:25,679",arabic:"هُنَا لَا تَحْتَاجُ أَنْ تُغْمِضَ عَيْنَيْكَ لِتَتَخَيَّلَ التَّارِيخَ",segs:[{ar:"هُنَا لَا تَحْتَاجُ",uz:"bu yerda sizga ehtiyoj yo‘q"},{ar:"أَنْ تُغْمِضَ عَيْنَيْكَ",uz:"ko‘zlaringizni yumishga"},{ar:"لِتَتَخَيَّلَ التَّارِيخَ",uz:"tarixni tasavvur qilish uchun"}],full_uz:"Bu yerda tarixni tasavvur qilish uchun ko‘zlaringizni yumishingizga hojat yo‘q.",note:"أَغْمَضَ عَيْنَيْهِ — ko‘zlarini yumoq."},
{num:193,time:"00:15:25,679 --> 00:15:33,079",arabic:"فَهُوَ مَاثِلٌ أَمَامَكَ فِي أَعْمِدَةٍ نُحِتَتْ مُنْذُ آلَافِ السِّنِينَ",segs:[{ar:"فَهُوَ مَاثِلٌ أَمَامَكَ",uz:"chunki u ko‘z oldingizda namoyon"},{ar:"فِي أَعْمِدَةٍ",uz:"ustunlarda"},{ar:"نُحِتَتْ مُنْذُ آلَافِ السِّنِينَ",uz:"minglab yillar oldin o‘yilgan"}],full_uz:"Chunki u minglab yillar oldin o‘yilgan ustunlarda ko‘z oldingizda namoyon.",note:"مَاثِلٌ — ko‘z oldida namoyon, mavjud."},
{num:194,time:"00:15:33,080 --> 00:15:40,400",arabic:"وَفِي مُدَرَّجٍ حَجَرِيٍّ يُعَانِقُ السَّمَاءَ",segs:[{ar:"وَفِي مُدَرَّجٍ حَجَرِيٍّ",uz:"va tosh amfiteatrda"},{ar:"يُعَانِقُ السَّمَاءَ",uz:"osmonni quchoqlaydigan"}],full_uz:"Va osmonni quchoqlab turgan tosh amfiteatrda.",note:"مُدَرَّجٌ — amfiteatr, pog‘onali tomosha maydoni."},
{num:195,time:"00:15:40,400 --> 00:15:46,560",arabic:"كَأَنَّهُ لَا يَزَالُ يَنْتَظِرُ جُمْهُورًا يَعُودُ",segs:[{ar:"كَأَنَّهُ لَا يَزَالُ يَنْتَظِرُ",uz:"go‘yo u hamon kutayotgandek"},{ar:"جُمْهُورًا يَعُودُ",uz:"qaytib keladigan tomoshabinlarni"}],full_uz:"Go‘yo u qaytib keladigan tomoshabinlarni hamon kutayotgandek.",note:"جُمْهُورٌ — tomoshabinlar, omma."},
{num:196,time:"00:15:46,560 --> 00:15:52,360",arabic:"سَبَسْطِيَةُ لَيْسَتْ مُجَرَّدَ قَرْيَةٍ",segs:null,full_uz:"Sabastiya shunchaki qishloq emas.",note:null},
{num:197,time:"00:15:52,360 --> 00:15:54,840",arabic:"إِنَّهَا مُتْحَفٌ مَفْتُوحٌ",segs:null,full_uz:"U ochiq muzeydir.",note:null},
{num:198,time:"00:15:54,840 --> 00:16:01,759",arabic:"يَمْزِجُ مَا بَيْنَ الْكَنْعَانِيِّ وَالرُّومَانِيِّ وَالْبَيْزَنْطِيِّ وَالْإِسْلَامِيِّ",segs:[{ar:"يَمْزِجُ مَا بَيْنَ الْكَنْعَانِيِّ وَالرُّومَانِيِّ",uz:"kan’oniy va Rimiy unsurlarni uyg‘unlashtiradi"},{ar:"وَالْبَيْزَنْطِيِّ وَالْإِسْلَامِيِّ",uz:"Vizantiya va islomiy unsurlarni ham"}],full_uz:"U kan’oniy, Rimiy, Vizantiya va islomiy merosni uyg‘unlashtiradi.",note:"يَمْزِجُ — aralashtirmoq, uyg‘unlashtirmoq."},
{num:199,time:"00:16:01,759 --> 00:16:09,159",arabic:"وَكُلُّ حَجَرٍ فِيهَا يَحْفَظُ سِرًّا أَوْ دُعَاءً",segs:[{ar:"وَكُلُّ حَجَرٍ فِيهَا",uz:"undagi har bir tosh"},{ar:"يَحْفَظُ سِرًّا أَوْ دُعَاءً",uz:"bir sir yoki duoni saqlaydi"}],full_uz:"Undagi har bir tosh bir sir yoki duoni saqlaydi.",note:null},
{num:200,time:"00:16:09,159 --> 00:16:13,799",arabic:"تَمْشِي فِي شَوَارِعِهَا الْقَدِيمَةِ",segs:null,full_uz:"Uning qadimiy ko‘chalarida yurasiz.",note:null},
{num:201,time:"00:16:13,799 --> 00:16:17,840",arabic:"فَتَلْمَسُ بِأَطْرَافِ أَصَابِعِكَ حَضَارَةً لَمْ تَمُتْ",segs:[{ar:"فَتَلْمَسُ بِأَطْرَافِ أَصَابِعِكَ",uz:"barmoqlaringiz uchlari bilan teginasiz"},{ar:"حَضَارَةً لَمْ تَمُتْ",uz:"o‘lmagan sivilizatsiyaga"}],full_uz:"Shunda barmoqlaringiz uchlari bilan o‘lmagan sivilizatsiyaga teginasiz.",note:"أَطْرَافُ الْأَصَابِعِ — barmoqlar uchlari."},
{num:202,time:"00:16:17,840 --> 00:16:24,600",arabic:"وَتَرَى فِي وُجُوهِ أَهْلِهَا مَزِيجًا مِنَ الِاعْتِزَازِ وَالثَّبَاتِ وَالْكَرَامَةِ",segs:[{ar:"وَتَرَى فِي وُجُوهِ أَهْلِهَا",uz:"uning aholisi yuzlarida ko‘rasiz"},{ar:"مَزِيجًا مِنَ الِاعْتِزَازِ وَالثَّبَاتِ وَالْكَرَامَةِ",uz:"g‘urur, sobitlik va qadr-qimmat qorishmasini"}],full_uz:"Uning aholisi yuzlarida g‘urur, sobitlik va qadr-qimmat qorishmasini ko‘rasiz.",note:"الِاعْتِزَازُ — faxr, g‘urur. الثَّبَاتُ — sobitlik."},
{num:203,time:"00:16:24,600 --> 00:16:30,679",arabic:"وَحِينَ تَغْرُبُ الشَّمْسُ خَلْفَ التِّلَالِ",segs:[{ar:"وَحِينَ تَغْرُبُ الشَّمْسُ",uz:"quyosh botganda"},{ar:"خَلْفَ التِّلَالِ",uz:"tepaliklar ortida"}],full_uz:"Quyosh tepaliklar ortida botganda.",note:null},
{num:204,time:"00:16:30,679 --> 00:16:35,359",arabic:"تَتَحَوَّلُ سَبَسْطِيَةُ إِلَى لَوْحَةٍ ذَهَبِيَّةٍ",segs:[{ar:"تَتَحَوَّلُ سَبَسْطِيَةُ",uz:"Sabastiya aylanadi"},{ar:"إِلَى لَوْحَةٍ ذَهَبِيَّةٍ",uz:"oltin rangli manzaraga"}],full_uz:"Sabastiya oltin rangli manzaraga aylanadi.",note:null},
{num:205,time:"00:16:35,359 --> 00:16:41,319",arabic:"يَرْتَفِعُ فِيهَا الْأَذَانُ مِنْ مَسْجِدٍ قَدِيمٍ",segs:[{ar:"يَرْتَفِعُ فِيهَا الْأَذَانُ",uz:"unda azon ovozi ko‘tariladi"},{ar:"مِنْ مَسْجِدٍ قَدِيمٍ",uz:"qadimiy masjiddan"}],full_uz:"U yerda qadimiy masjiddan azon ovozi yangraydi.",note:null},
{num:206,time:"00:16:41,319 --> 00:16:47,079",arabic:"بِجَوَارِ أَطْلَالٍ تُذَكِّرُ بِأَنَّ هَذَا الْمَكَانَ كَانَ يَوْمًا مَرْكَزَ الْعَالَمِ",segs:[{ar:"بِجَوَارِ أَطْلَالٍ",uz:"xarobalar yonida"},{ar:"تُذَكِّرُ بِأَنَّ هَذَا الْمَكَانَ",uz:"bu joy ... ekanini eslatadigan"},{ar:"كَانَ يَوْمًا مَرْكَزَ الْعَالَمِ",uz:"bir vaqtlar dunyo markazi bo‘lganini"}],full_uz:"Bir vaqtlar bu joy dunyo markazi bo‘lganini eslatadigan xarobalar yonida.",note:null},
{num:207,time:"00:16:47,079 --> 00:16:49,819",arabic:"وَلَا يَزَالُ مَرْكَزَ الرُّوحِ",segs:null,full_uz:"Va hamon ruh markazidir.",note:"لَا يَزَالُ — hamon."},
{num:208,time:"00:16:49,819 --> 00:16:56,120",arabic:"غَزَّةُ لَيْسَتْ فَقَطْ مَدِينَةً",segs:null,full_uz:"G‘azo shunchaki shahar emas.",note:null},
{num:209,time:"00:16:56,120 --> 00:16:59,779",arabic:"بَلْ قَصِيدَةٌ مَحْفُورَةٌ فِي الرَّمْلِ وَالْبَحْرِ",segs:[{ar:"بَلْ قَصِيدَةٌ مَحْفُورَةٌ",uz:"balki o‘yib yozilgan she’r"},{ar:"فِي الرَّمْلِ وَالْبَحْرِ",uz:"qum va dengizda"}],full_uz:"Balki qum va dengizga o‘yib yozilgan she’rdir.",note:"مَحْفُورٌ — o‘yib yozilgan."},
{num:210,time:"00:16:59,779 --> 00:17:03,779",arabic:"مَدِينَةٌ تَقِفُ عَلَى حَافَّةِ التَّارِيخِ وَالِانْتِظَارِ",segs:[{ar:"مَدِينَةٌ تَقِفُ عَلَى حَافَّةِ التَّارِيخِ",uz:"tarix chekkasida turgan shahar"},{ar:"وَالِانْتِظَارِ",uz:"va kutish"}],full_uz:"Tarix va kutish chekkasida turgan shahar.",note:"حَافَّةٌ — chekka."},
{num:211,time:"00:17:03,779 --> 00:17:07,460",arabic:"وَتَبْتَسِمُ رَغْمَ مَا مَرَّ بِهَا مِنْ أَلَمٍ",segs:[{ar:"وَتَبْتَسِمُ",uz:"va tabassum qiladi"},{ar:"رَغْمَ مَا مَرَّ بِهَا مِنْ أَلَمٍ",uz:"boshidan kechirgan og‘riqlarga qaramay"}],full_uz:"Boshidan kechirgan og‘riqlarga qaramay tabassum qiladi.",note:"مَرَّ بِـ — boshidan kechirmoq."},
{num:212,time:"00:17:07,460 --> 00:17:16,980",arabic:"حِينَ تَسِيرُ فِي شَوَارِعِهَا الْقَدِيمَةِ",segs:null,full_uz:"Uning qadimiy ko‘chalarida yurganingizda.",note:null},
{num:213,time:"00:17:16,980 --> 00:17:22,139",arabic:"تَشْعُرُ وَكَأَنَّكَ تَمْشِي فَوْقَ طَبَقَاتٍ مِنَ الْمَجْدِ وَالْعَزِيمَةِ",segs:[{ar:"تَشْعُرُ وَكَأَنَّكَ تَمْشِي",uz:"go‘yo yurgandek his qilasiz"},{ar:"فَوْقَ طَبَقَاتٍ مِنَ الْمَجْدِ وَالْعَزِيمَةِ",uz:"shon-sharaf va qat’iyat qatlamlari ustida"}],full_uz:"Go‘yo shon-sharaf va qat’iyat qatlamlari ustida yurgandek his qilasiz.",note:"طَبَقَاتٌ — qatlamlar."},
{num:214,time:"00:17:22,139 --> 00:17:25,279",arabic:"مُنْذُ الْكَنْعَانِيِّينَ حَتَّى يَوْمِنَا هَذَا",segs:null,full_uz:"Kan’oniylardan to bugungi kunimizgacha.",note:null},
{num:215,time:"00:17:25,279 --> 00:17:29,019",arabic:"ظَلَّتْ غَزَّةُ نُقْطَةَ الْتِقَاءِ الْحَضَارَاتِ",segs:[{ar:"ظَلَّتْ غَزَّةُ",uz:"G‘azo bo‘lib qoldi"},{ar:"نُقْطَةَ الْتِقَاءِ الْحَضَارَاتِ",uz:"sivilizatsiyalar uchrashuv nuqtasi"}],full_uz:"G‘azo sivilizatsiyalar uchrashuv nuqtasi bo‘lib qoldi.",note:"نُقْطَةُ الْتِقَاءِ — uchrashuv nuqtasi."},
{num:216,time:"00:17:29,019 --> 00:17:32,299",arabic:"وَمَسْرَحًا لِقُوَّةِ الْإِنْسَانِ عَلَى الْبَقَاءِ",segs:[{ar:"وَمَسْرَحًا",uz:"va maydon bo‘lib"},{ar:"لِقُوَّةِ الْإِنْسَانِ عَلَى الْبَقَاءِ",uz:"insonning omon qolish qudrati uchun"}],full_uz:"Va insonning omon qolish qudrati namoyon bo‘ladigan maydon bo‘lib qoldi.",note:"الْبَقَاءُ — qolish, omon qolish."},
{num:217,time:"00:17:32,299 --> 00:17:40,099",arabic:"يَحْتَضِنُهَا الْبَحْرُ كَأُمٍّ حَزِينَةٍ",segs:[{ar:"يَحْتَضِنُهَا الْبَحْرُ",uz:"dengiz uni bag‘riga oladi"},{ar:"كَأُمٍّ حَزِينَةٍ",uz:"g‘amgin ona kabi"}],full_uz:"Dengiz uni g‘amgin ona kabi bag‘riga oladi.",note:null},
{num:218,time:"00:17:40,099 --> 00:17:43,599",arabic:"تُغَنِّي لِوَلَدِهَا الْعَائِدِ مِنْ رِحْلَةِ الْعَنَاءِ",segs:[{ar:"تُغَنِّي لِوَلَدِهَا",uz:"farzandiga kuylaydi"},{ar:"الْعَائِدِ مِنْ رِحْلَةِ الْعَنَاءِ",uz:"mashaqqatli safardan qaytayotgan"}],full_uz:"Mashaqqatli safardan qaytayotgan farzandiga kuylaydi.",note:"الْعَنَاءُ — mashaqqat, zahmat."},
{num:219,time:"00:17:43,599 --> 00:17:45,639",arabic:"وَعَلَى شَوَاطِئِهَا",segs:null,full_uz:"Va uning sohillarida.",note:null},
{num:220,time:"00:17:45,639 --> 00:17:49,119",arabic:"يَلْعَبُ الْأَطْفَالُ رَغْمَ مَا يَحُومُ فِي السَّمَاءِ",segs:[{ar:"يَلْعَبُ الْأَطْفَالُ",uz:"bolalar o‘ynaydi"},{ar:"رَغْمَ مَا يَحُومُ فِي السَّمَاءِ",uz:"osmonda aylanib yurgan narsalarga qaramay"}],full_uz:"Osmonda aylanib yurgan narsalarga qaramay bolalar o‘ynaydi.",note:"يَحُومُ — aylanib yurmoq."},
{num:221,time:"00:17:49,119 --> 00:17:51,900",arabic:"يَرْسُمُونَ الْحُلْمَ عَلَى الرِّمَالِ",segs:null,full_uz:"Ular qum ustiga orzuni chizadilar.",note:null},
{num:222,time:"00:17:51,900 --> 00:17:56,539",arabic:"وَيَزْرَعُونَ الْأَمَلَ فِي مَكَانٍ جَفَّتْ فِيهِ الدُّمُوعُ",segs:[{ar:"وَيَزْرَعُونَ الْأَمَلَ",uz:"va umidni ekadilar"},{ar:"فِي مَكَانٍ جَفَّتْ فِيهِ الدُّمُوعُ",uz:"ko‘z yoshlar qurigan joyga"}],full_uz:"Va ko‘z yoshlar qurigan joyda umidni ekadilar.",note:"جَفَّ — qurimoq."},
{num:223,time:"00:17:56,539 --> 00:18:07,920",arabic:"فِي قَلْبِ الْمَدِينَةِ يَنْهَضُ الْجَامِعُ الْعُمَرِيُّ الْكَبِيرُ بِمَآذِنِهِ الَّتِي عَانَقَتْ قُرُونًا مِنَ الصَّلَاةِ",segs:[{ar:"فِي قَلْبِ الْمَدِينَةِ",uz:"shahar markazida"},{ar:"يَنْهَضُ الْجَامِعُ الْعُمَرِيُّ الْكَبِيرُ",uz:"Buyuk Umariy jome masjidi qad rostlaydi"},{ar:"بِمَآذِنِهِ",uz:"o‘z minoralari bilan"},{ar:"الَّتِي عَانَقَتْ قُرُونًا مِنَ الصَّلَاةِ",uz:"asrlar davom etgan ibodatlarni bag‘riga olgan"}],full_uz:"Shahar markazida asrlar davom etgan ibodatlarni bag‘riga olgan minoralari bilan Buyuk Umariy jome masjidi qad rostlaydi.",note:"عَانَقَتْ — quchoqlagan."},
{num:224,time:"00:18:07,920 --> 00:18:15,480",arabic:"وَمُدَرَّجَاتُ كَنِيسَةِ الْقِدِّيسِ بَرْفِيرِيُوسَ حَيْثُ تُعَانِقُ الْأَجْرَاسُ صَوْتَ الْأَذَانِ",segs:[{ar:"وَمُدَرَّجَاتُ كَنِيسَةِ الْقِدِّيسِ بَرْفِيرِيُوسَ",uz:"Avliyo Porfiriy cherkovining pog‘onalari"},{ar:"حَيْثُ تُعَانِقُ الْأَجْرَاسُ",uz:"u yerda qo‘ng‘iroqlar quchoqlaydi"},{ar:"صَوْتَ الْأَذَانِ",uz:"azon ovozini"}],full_uz:"Avliyo Porfiriy cherkovining pog‘onalari, u yerda qo‘ng‘iroqlar azon ovozini quchoqlab turadi.",note:"مُدَرَّجَاتٌ — pog‘onalar, qatorlar."},
{num:225,time:"00:18:15,480 --> 00:18:26,700",arabic:"وَغَزَّةُ رَغْمَ الْقُيُودِ تَفِيضُ بِالْحَيَاةِ فِي أَسْوَاقِهَا الْمُزْدَحِمَةِ",segs:[{ar:"وَغَزَّةُ رَغْمَ الْقُيُودِ",uz:"G‘azo cheklovlarga qaramay"},{ar:"تَفِيضُ بِالْحَيَاةِ",uz:"hayot bilan to‘lib-toshadi"},{ar:"فِي أَسْوَاقِهَا الْمُزْدَحِمَةِ",uz:"uning gavjum bozorlarida"}],full_uz:"G‘azo cheklovlarga qaramay gavjum bozorlarida hayot bilan to‘lib-toshadi.",note:"تَفِيضُ — toshib ketmoq, mo‘l bo‘lmoq."},
{num:226,time:"00:18:26,700 --> 00:18:31,599",arabic:"فِي أَزِقَّتِهَا الَّتِي تَفُوحُ بِرَائِحَةِ الزَّعْتَرِ وَالْخُبْزِ",segs:[{ar:"فِي أَزِقَّتِهَا",uz:"uning tor ko‘chalarida"},{ar:"الَّتِي تَفُوحُ بِرَائِحَةِ الزَّعْتَرِ وَالْخُبْزِ",uz:"za’atar va non hidiga to‘la"}],full_uz:"Za’atar va non hidi taralib turadigan tor ko‘chalarida.",note:"تَفُوحُ — hid taratmoq."},
{num:227,time:"00:18:31,599 --> 00:18:34,620",arabic:"فِي وُجُوهِ نِسَائِهَا",segs:null,full_uz:"Uning ayollari yuzlarida.",note:null},
{num:228,time:"00:18:34,620 --> 00:18:37,740",arabic:"فِي ضَحِكَاتِ أَطْفَالِهَا",segs:null,full_uz:"Uning bolalari kulgisida.",note:null},
{num:229,time:"00:18:37,740 --> 00:18:42,140",arabic:"فِي كُلِّ زَاوِيَةٍ نَبْضٌ لَا يُقْهَرُ",segs:[{ar:"فِي كُلِّ زَاوِيَةٍ",uz:"har bir burchakda"},{ar:"نَبْضٌ لَا يُقْهَرُ",uz:"yengib bo‘lmaydigan jo‘shqinlik"}],full_uz:"Har bir burchakda yengib bo‘lmaydigan jo‘shqinlik bor.",note:"يُقْهَرُ — yengilmoq, mag‘lub bo‘lmoq."},
{num:230,time:"00:18:42,140 --> 00:18:47,060",arabic:"هُنَا الْجَمَالُ لَيْسَ فِي الْمَشْهَدِ فَقَطْ",segs:[{ar:"هُنَا الْجَمَالُ",uz:"bu yerda go‘zallik"},{ar:"لَيْسَ فِي الْمَشْهَدِ فَقَطْ",uz:"faqat manzarada emas"}],full_uz:"Bu yerda go‘zallik faqat manzarada emas.",note:null},
{num:231,time:"00:18:47,060 --> 00:18:52,580",arabic:"بَلْ فِي الْقُدْرَةِ الْعَجِيبَةِ عَلَى الْبَقَاءِ وَالْحُبِّ وَالْحُلْمِ",segs:[{ar:"بَلْ فِي الْقُدْرَةِ الْعَجِيبَةِ",uz:"balki ajoyib qobiliyatda"},{ar:"عَلَى الْبَقَاءِ وَالْحُبِّ وَالْحُلْمِ",uz:"qolish, sevish va orzu qilishga"}],full_uz:"Balki qolish, sevish va orzu qilishning ajoyib qobiliyatidadir.",note:null},
{num:232,time:"00:18:52,580 --> 00:18:58,980",arabic:"فِي كُلِّ بَيْتٍ فَارَقَ الضَّوْءَ يَنْبُتُ بَيْتٌ جَدِيدٌ مِنَ الْإِرَادَةِ",segs:[{ar:"فِي كُلِّ بَيْتٍ فَارَقَ الضَّوْءَ",uz:"yorug‘likni tark etgan har bir uyda"},{ar:"يَنْبُتُ بَيْتٌ جَدِيدٌ",uz:"yangi bir uy unib chiqadi"},{ar:"مِنَ الْإِرَادَةِ",uz:"irodadan"}],full_uz:"Yorug‘likni tark etgan har bir uyda irodadan yangi bir uy unib chiqadi.",note:"فَارَقَ — tark etmoq, ajralmoq. يَنْبُتُ — unib chiqmoq."},
{num:233,time:"00:18:58,980 --> 00:19:08,600",arabic:"غَزَّةُ مَدِينَةٌ تَمْشِي عَلَى جِرَاحِهَا كَأَنَّهَا جَنَاحَيْنِ",segs:[{ar:"غَزَّةُ مَدِينَةٌ تَمْشِي عَلَى جِرَاحِهَا",uz:"G‘azo yaralari ustida yuradigan shahardir"},{ar:"كَأَنَّهَا جَنَاحَيْنِ",uz:"go‘yo ular ikki qanotdek"}],full_uz:"G‘azo go‘yo yaralari ikki qanotdek, ular ustida yuradigan shahardir.",note:"جَرَاحٌ — yaralar."},
{num:234,time:"00:19:08,599 --> 00:19:12,599",arabic:"وَتُعَلِّمُ الْعَالَمَ أَنَّ الْكَرَامَةَ لَا تُنْسَى",segs:[{ar:"وَتُعَلِّمُ الْعَالَمَ",uz:"va dunyoga o‘rgatadi"},{ar:"أَنَّ الْكَرَامَةَ لَا تُنْسَى",uz:"qadr-qimmat unutilmasligini"}],full_uz:"Va dunyoga qadr-qimmat unutilmasligini o‘rgatadi.",note:"الْكَرَامَةُ — qadr-qimmat, sharaf."},
{num:235,time:"00:19:12,599 --> 00:19:17,339",arabic:"وَأَنَّ حَتَّى فِي الظَّلَامِ يُمْكِنُ لِلرُّوحِ أَنْ تُضِيءَ الْكَوْنَ",segs:[{ar:"وَأَنَّ حَتَّى فِي الظَّلَامِ",uz:"hatto qorong‘ulikda ham"},{ar:"يُمْكِنُ لِلرُّوحِ",uz:"ruh uchun mumkin"},{ar:"أَنْ تُضِيءَ الْكَوْنَ",uz:"koinotni yoritish"}],full_uz:"Va hatto qorong‘ulikda ham ruh koinotni yoritishi mumkinligini.",note:"تُضِيءُ — yoritmoq."},
{num:236,time:"00:19:17,339 --> 00:19:25,399",arabic:"فِي فِلَسْطِينِ لَا تُقَاسُ الْعَجَائِبُ بِالْحَجْمِ وَلَا تُعَدُّ بِالْعَدَدِ",segs:[{ar:"فِي فِلَسْطِينِ",uz:"Falastinda"},{ar:"لَا تُقَاسُ الْعَجَائِبُ بِالْحَجْمِ",uz:"mo‘jizalar hajm bilan o‘lchanmaydi"},{ar:"وَلَا تُعَدُّ بِالْعَدَدِ",uz:"va son bilan sanalmaydi"}],full_uz:"Falastinda mo‘jizalar hajm bilan o‘lchanmaydi va son bilan sanalmaydi.",note:null},
{num:237,time:"00:19:25,399 --> 00:19:29,679",arabic:"بَلْ تُقَاسُ بِمَا تَتْرُكُهُ فِيكَ مِنْ أَثَرٍ لَا يُمْحَى",segs:[{ar:"بَلْ تُقَاسُ بِمَا تَتْرُكُهُ فِيكَ",uz:"balki sizda qoldiradigan narsa bilan o‘lchanadi"},{ar:"مِنْ أَثَرٍ لَا يُمْحَى",uz:"o‘chmaydigan izdan"}],full_uz:"Balki sizda o‘chmaydigan iz qoldirishi bilan o‘lchanadi.",note:"يُمْحَى — o‘chirilmoq, yo‘q qilinmoq."},
{num:238,time:"00:19:29,679 --> 00:19:32,119",arabic:"وَدَهْشَةٍ لَا تَنْطَفِئُ",segs:null,full_uz:"Va so‘nmaydigan hayrat bilan.",note:"تَنْطَفِئُ — so‘nmoq."},
{num:239,time:"00:19:32,119 --> 00:19:35,740",arabic:"بَلَدٌ صَغِيرٌ فِي الْخَرِيطَةِ",segs:null,full_uz:"Xaritada kichik bir yurt.",note:"بَلَدٌ — mamlakat, yurt."},
{num:240,time:"00:19:35,740 --> 00:19:39,079",arabic:"لَكِنْ فِي قَلْبِهِ كَوْنٌ وَاسِعٌ مِنَ الْمَعَانِي",segs:[{ar:"لَكِنْ فِي قَلْبِهِ",uz:"ammo uning qalbida"},{ar:"كَوْنٌ وَاسِعٌ مِنَ الْمَعَانِي",uz:"ma’nolarning keng bir koinoti bor"}],full_uz:"Ammo uning qalbida ma’nolarning keng bir koinoti bor.",note:null},
{num:241,time:"00:19:39,079 --> 00:19:43,740",arabic:"مِنَ الْقُدْسِ الَّتِي تُصَلِّي فِي صَمْتِ الْحِجَارَةِ",segs:[{ar:"مِنَ الْقُدْسِ",uz:"Quddusdan"},{ar:"الَّتِي تُصَلِّي فِي صَمْتِ الْحِجَارَةِ",uz:"toshlar sukunatida ibodat qiladigan"}],full_uz:"Toshlar sukunatida ibodat qiladigan Quddusdan.",note:null},
{num:242,time:"00:19:44,579 --> 00:19:51,740",arabic:"إِلَى الْبَحْرِ الْمَيِّتِ حَيْثُ تَهْوِي الرُّوحُ نَحْوَ الْأَعْمَاقِ",segs:[{ar:"إِلَى الْبَحْرِ الْمَيِّتِ",uz:"O‘lik dengizgacha"},{ar:"حَيْثُ تَهْوِي الرُّوحُ نَحْوَ الْأَعْمَاقِ",uz:"u yerda ruh qa’r tomon qulaydi"}],full_uz:"O‘lik dengizgacha, u yerda ruh qa’r tomon qulaydi.",note:"تَهْوِي — qulamoq, pastga tushmoq."},
{num:243,time:"00:19:52,400 --> 00:20:01,940",arabic:"مِنْ أَرْيَافٍ تُعَانِقُ الْغَيْمَ إِلَى جِبَالٍ تَهْمِسُ بِحِكَايَةِ الْأَوَّلِينَ",segs:[{ar:"مِنْ أَرْيَافٍ تُعَانِقُ الْغَيْمَ",uz:"bulutlarni quchoqlaydigan qishloqlardan"},{ar:"إِلَى جِبَالٍ تَهْمِسُ بِحِكَايَةِ الْأَوَّلِينَ",uz:"qadimgilar hikoyasini shivirlaydigan tog‘larga"}],full_uz:"Bulutlarni quchoqlaydigan qishloqlardan qadimgilar hikoyasini shivirlaydigan tog‘larga.",note:"أَرْيَافٌ — qishloq joylar, qishloqlar. الْأَوَّلُونَ — avvalgililar, qadimgilar."},
{num:244,time:"00:20:01,940 --> 00:20:06,059",arabic:"فِلَسْطِينُ لَيْسَتْ فَقَطْ أَرْضًا",segs:null,full_uz:"Falastin shunchaki yer emas.",note:null},
{num:245,time:"00:20:06,059 --> 00:20:08,880",arabic:"بَلْ نِدَاءٌ أَبَدِيٌّ لِلْجَمَالِ وَالصُّمُودِ",segs:[{ar:"بَلْ نِدَاءٌ أَبَدِيٌّ",uz:"balki abadiy bir nido"},{ar:"لِلْجَمَالِ وَالصُّمُودِ",uz:"go‘zallik va matonatga"}],full_uz:"Balki go‘zallik va matonatga abadiy bir nidodir.",note:"الصُّمُودُ — matonat, bardoshlilik."},
{num:246,time:"00:20:08,880 --> 00:20:13,539",arabic:"رِسَالَةٌ مِنْ نُورٍ وَتَارِيخٍ وَأَمَلٍ لَا يَنْكَسِرُ",segs:[{ar:"رِسَالَةٌ مِنْ نُورٍ وَتَارِيخٍ",uz:"nur va tarixdan iborat xabar"},{ar:"وَأَمَلٍ لَا يَنْكَسِرُ",uz:"va sinmaydigan umid"}],full_uz:"Nur, tarix va sinmaydigan umiddan iborat xabar.",note:null},
{num:247,time:"00:20:13,539 --> 00:20:23,559",arabic:"وَحِينَ تُغَادِرُهَا تَبْقَى جُزْءًا مِنْهَا سَاكِنًا فِيكَ",segs:[{ar:"وَحِينَ تُغَادِرُهَا",uz:"undan ketganingizda"},{ar:"تَبْقَى جُزْءًا مِنْهَا",uz:"uning bir qismi qoladi"},{ar:"سَاكِنًا فِيكَ",uz:"sizning ichingizda yashab"}],full_uz:"Undan ketganingizda ham uning bir qismi sizning ichingizda yashab qoladi.",note:"سَاكِنٌ — yashovchi, joylashgan."},
{num:248,time:"00:20:23,559 --> 00:20:26,539",arabic:"يَنْبِضُ كُلَّمَا نَظَرْتَ إِلَى الْأُفُقِ",segs:[{ar:"يَنْبِضُ",uz:"jo‘sh uradi"},{ar:"كُلَّمَا نَظَرْتَ إِلَى الْأُفُقِ",uz:"ufqqa har safar qaraganingizda"}],full_uz:"U ufqqa har safar qaraganingizda jo‘sh uradi.",note:"كُلَّمَا — har safar, qachonki har gal."},
{num:249,time:"00:20:26,539 --> 00:20:29,500",arabic:"وَكُلَّمَا سَمِعْتَ تَرَاتِيلَ السَّلَامِ",segs:[{ar:"وَكُلَّمَا سَمِعْتَ",uz:"va har safar eshitganingizda"},{ar:"تَرَاتِيلَ السَّلَامِ",uz:"tinchlik taronalarini"}],full_uz:"Va har safar tinchlik taronalarini eshitganingizda.",note:"تَرَاتِيلُ — taronalar, madhiyalar."},
{num:250,time:"00:20:29,500 --> 00:20:33,420",arabic:"فَهِيَ الْأَعْجُوبَةُ الَّتِي لَا تُشْبِهُ سِوَاهَا",segs:[{ar:"فَهِيَ الْأَعْجُوبَةُ",uz:"u mo‘jizadir"},{ar:"الَّتِي لَا تُشْبِهُ سِوَاهَا",uz:"o‘zidan boshqasiga o‘xshamaydigan"}],full_uz:"U o‘zidan boshqasiga o‘xshamaydigan mo‘jizadir.",note:"أَعْجُوبَةٌ — mo‘jiza, ajabtovur narsa."},
{num:251,time:"00:20:33,420 --> 00:20:39,279",arabic:"إِذَا لَمَسَتْكَ هَذِهِ الرِّحْلَةُ",segs:[{ar:"إِذَا لَمَسَتْكَ",uz:"agar sizga ta’sir qilgan bo‘lsa"},{ar:"هَذِهِ الرِّحْلَةُ",uz:"bu sayohat"}],full_uz:"Agar bu sayohat sizga ta’sir qilgan bo‘lsa.",note:"لَامَسَ — tegmoq, ta’sir qilmoq."},
{num:252,time:"00:20:39,279 --> 00:20:42,099",arabic:"شَارِكِ الْفِيدْيُوَ مَعَ مَنْ تُحِبُّ",segs:[{ar:"شَارِكِ الْفِيدْيُوَ",uz:"videoni ulashing"},{ar:"مَعَ مَنْ تُحِبُّ",uz:"sevgan insoningiz bilan"}],full_uz:"Videoni sevgan insoningiz bilan ulashing.",note:"شَارَكَ — ulashmoq, bo‘lishmoq."},
{num:253,time:"00:20:42,099 --> 00:20:43,920",arabic:"اتْرُكْ تَعْلِيقَكَ",segs:null,full_uz:"Izohingizni qoldiring.",note:"تَعْلِيقٌ — izoh, komment."},
{num:254,time:"00:20:43,920 --> 00:20:45,079",arabic:"وَحَدِّثْنَا",segs:null,full_uz:"Va bizga aytib bering.",note:"حَدَّثَ — gapirib bermoq, so‘zlab bermoq."},
{num:255,time:"00:20:45,079 --> 00:20:48,500",arabic:"أَيَّ مَكَانٍ فِي فِلَسْطِينِ خَطَفَ قَلْبَكَ",segs:[{ar:"أَيَّ مَكَانٍ فِي فِلَسْطِينِ",uz:"Falastindagi qaysi joy"},{ar:"خَطَفَ قَلْبَكَ",uz:"qalbingizni rom etdi"}],full_uz:"Falastindagi qaysi joy qalbingizni rom etdi?",note:"خَطَفَ قَلْبَ — qalbini rom etmoq, maftun qilmoq."},
{num:256,time:"00:20:48,500 --> 00:20:53,500",arabic:"وَلَا تَنْسَ الِاشْتِرَاكَ لِمَزِيدٍ مِنَ الرِّحْلَاتِ السَّاحِرَةِ حَوْلَ الْعَالَمِ",segs:[{ar:"وَلَا تَنْسَ الِاشْتِرَاكَ",uz:"obuna bo‘lishni unutmang"},{ar:"لِمَزِيدٍ مِنَ الرِّحْلَاتِ السَّاحِرَةِ",uz:"yana ko‘plab sehrli sayohatlar uchun"},{ar:"حَوْلَ الْعَالَمِ",uz:"dunyo bo‘ylab"}],full_uz:"Dunyo bo‘ylab yana ko‘plab sehrli sayohatlar uchun obuna bo‘lishni unutmang.",note:"سَاحِرٌ — sehrli, maftunkor."}
];

